const HSA_TOPICS_DATA = [{"name":"MEDICAL SCHOOL MD + DO","list_label":"MEDICAL SCHOOL MD + DO","phase":"","category":"Program Overview","sections":[{"heading":"4-YEAR SCHOOL + LICENSING EXAM EDITION | CASE-BASED | VIDEO-FIRST | BOARD-ALIGNED — PURPOSE","type":"paragraph","text":"A rigorous, cross-school curriculum designed to help a learner master medical-school coursework, clinical clerkships, and the major U.S. licensing-exam domains. It is not a guarantee of passing and it does not replace a medical school curriculum, faculty supervision, patient-care training, or official exam guidance."},{"heading":"4-YEAR SCHOOL + LICENSING EXAM EDITION | CASE-BASED | VIDEO-FIRST | BOARD-ALIGNED — PURPOSE","type":"table","columns":["LEARNING ROUTE","WHAT IT DOES"],"rows":[["YEAR 1 - FOUNDATIONS","Build anatomy, cellular/molecular science, biochemistry, physiology, microbiology, immunology, pharmacology, pathology, clinical skills, evidence-based medicine, ethics and OPP/OMM (DO)."],["YEAR 2 - SYSTEMS + DISEASE","Integrate organ-system physiology, pathology, pharmacology, microbiology, diagnosis and therapeutics; prepare for Step 1 / COMLEX Level 1."],["YEAR 3 - CORE CLERKSHIPS","Learn supervised patient care, clinical reasoning and specialty knowledge while preparing for NBME Subject Exams / COMAT and Step 2 / Level 2."],["YEAR 4 - ADVANCED CLINICAL","Sub-internship, emergency/critical care, electives, advanced patient management, residency readiness and transition to internship."],["LICENSING EXAMS","USMLE Step 1, Step 2 CK and Step 3; COMLEX-USA Level 1, Level 2-CE and Level 3; NBME clinical subject exams and COMAT."]]}],"page":0},{"name":"HOW TO USE THIS PROGRAM","list_label":"HOW TO USE THIS PROGRAM","phase":"","category":"Program Overview","sections":[{"heading":"THE MASTERY LOOP","type":"paragraph","text":"For each course or clerkship: Learn -> Retrieve -> Apply -> Test -> Remediate -> Re-test. Passive watching alone is not sufficient. Every block should end with question-based retrieval and an assessment tied to the relevant school or licensing-exam blueprint."},{"heading":"Recommended study architecture","type":"table","columns":["Layer","Goal","Typical tools"],"rows":[["1. Concept build","Understand mechanisms and mental models.","School lectures + substantive videos + core text/notes."],["2. Active recall","Make key facts and relationships retrievable.","Spaced repetition / flashcards / closed-book recall."],["3. Question practice","Translate knowledge into vignette reasoning.","UWorld, AMBOSS, TrueLearn/COMBANK, school question banks."],["4. Clinical application","Use knowledge in cases, physical exam and management decisions.","Standardized patients, simulation, bedside teaching, OnlineMedEd, Stanford Medicine 25."],["5. Readiness check","Use external assessments before high-stakes exams.","NBME CBSSA/CCSSA/CSMS; USMLE sample interface; NBOME/COMAT-SE."],["6. Remediation","Turn misses into a targeted plan.","Error log -> targeted video/article -> new questions -> timed reassessment."]]},{"heading":"Recommended study architecture — Rules for this Academy","type":"bullets","items":["Official blueprints are the source of truth. Exam formats and content can change; always verify on USMLE/NBME/NBOME before test day.","School exams come first during the block. Map each school objective to the Academy module, then add board-style questions on the same topic.","Questions are learning tools. Review why every option is right or wrong, not just the correct answer.","Videos are selected for depth. Use long-form teaching to build mechanisms; use short clips only when they efficiently demonstrate a focused exam or procedure.","Clinical competence requires supervised practice. No video curriculum substitutes for anatomy lab, standardized patients, simulation, clerkships or direct patient care."]}],"page":1},{"name":"BENCHMARK BASIS","list_label":"BENCHMARK BASIS","phase":"","category":"Program Overview","sections":[{"heading":"","type":"paragraph","text":"The program is intentionally cross-school rather than a copy of any single curriculum."},{"heading":"","type":"table","columns":["Benchmark","Current signal","What we borrow","Link"],"rows":[["University of Washington School of Medicine","18-month Foundations + Patient Care + Explore & Focus.","Integrated preclinical and clinical phases.","https://education.uwmedicine.org/curriculum/"],["Stanford Medicine","Anatomy; molecular/cellular/genetic medicine; biochemistry; pharmacology; microbiology; immunology; organ systems + clinical practice.","Strong integrated pre-clerkship model.","https://med.stanford.edu/md/mdhandbook/section-4--discovery-curriculum-overview/4-3--academic-requirements-for-graduation.html"],["Harvard Medical School Pathways","Foundations; integrated pathophysiology; Practice of Medicine; principal clinical experience; advanced science.","Early clinical integration + advanced post-clerkship science.","https://meded.hms.harvard.edu/pathways"],["Johns Hopkins Genes to Society","Scientific foundations + organ systems integrating biochemistry, cell biology, epidemiology, pathology and pharmacology.","Mechanism-to-patient integration.","https://www.hopkinsmedicine.org/som/curriculum/genes-to-society/curriculum"],["PNWU-COM","OMS1-2 systems-based preclinical education; OMS3 core rotations; OMS4 emergency/electives; OPP/OMM longitudinally.","DO-specific competencies + COMLEX integration.","https://www.pnwu.edu/academics/college-of-osteopathic-medicine/curriculum/"]]},{"heading":"Why the curriculum is organized by year anyway","type":"paragraph","text":"Many modern schools compress the traditional first two years, begin clerkships earlier, or integrate disciplines across organ systems. This Academy uses a four-year learner map because it is easy to navigate, but each module can be moved earlier or later to match the student's actual school schedule."}],"page":2},{"name":"FOUR-YEAR MEDICAL SCHOOL MAP","list_label":"FOUR-YEAR MEDICAL SCHOOL MAP","phase":"","category":"Program Overview","sections":[{"heading":"","type":"table","columns":["Phase","Core curriculum","Primary assessment focus"],"rows":[["YEAR 1 - FOUNDATION","Anatomy/Histology/Embryology; Cell & Molecular Biology; Genetics; Biochemistry; Physiology; Immunology; Microbiology; Pharmacology Foundations; Pathology Foundations; Neuroscience/Behavior; Biostatistics/Epidemiology/EBM; Clinical Skills I; Ethics/Professionalism/Health Systems; OPP/OMM for DO.","In-house block exams, practicals, OSCE-style skills; early board-style questions."],["YEAR 2 - SYSTEMS + DISEASE","Cardiovascular; Respiratory; Renal; GI/Liver/Nutrition; Endocrine; Reproductive; Hematology/Oncology; Infectious Disease; MSK/Rheum/Derm; Neuro/Psych; integrated systemic pathology/pharmacology; Clinical Skills II.","In-house systems exams + USMLE Step 1 / COMLEX Level 1 dedicated prep."],["YEAR 3 - CORE CLINICAL","Internal Medicine; Surgery; Family Medicine; Pediatrics; OB/GYN; Psychiatry; Neurology; Emergency Medicine where required; longitudinal OPP/OMM for DO.","NBME Clinical Science Subject Exams / COMAT; clinical evaluations; OSCE; begin Step 2 CK / Level 2-CE."],["YEAR 4 - ADVANCED CLINICAL","Sub-internship; Emergency Medicine; Critical Care; specialty electives; radiology; anesthesiology; procedures; transition to internship; residency application.","Step 2 CK / COMLEX Level 2-CE if not completed; school capstone/OSCE; residency readiness."]]},{"heading":"POST-GRADUATION LICENSURE","type":"paragraph","text":"USMLE Step 3 and COMLEX-USA Level 3 belong primarily to the residency/independent-practice transition. They are included in this Academy as a preview and future study path, not as a Year 4 medical-school requirement for every learner."}],"page":3},{"name":"PROFESSIONAL EXAM MAP - 2026/27","list_label":"PROFESSIONAL EXAM MAP - 2026/27","phase":"","category":"Program Overview","sections":[{"heading":"","type":"table","columns":["Exam","What it tests","Current format / status","Link"],"rows":[["USMLE Step 1","Foundational science applied to disease mechanisms.","Pass/fail. Since May 14, 2026: 14 x 30-minute blocks; up to 280 items; 8-hour session.","https://www.usmle.org/step-exams/step-1"],["COMLEX-USA Level 1","Foundational biomedical science + osteopathic principles/practice.","Pass/fail. 2026 format: 320 single-best-answer items across two 4-hour sessions.","https://www.nbome.org/assessments/comlex-usa/examination-format/"],["NBME Subject Exams","Clinical science at the end of clerkships.","Common subjects include Medicine, Surgery, Pediatrics, OB/GYN, Psychiatry, Family Medicine, Neurology and Emergency Medicine.","https://www.nbme.org/examinees/self-assessments/clinical-science-mastery-series/"],["COMAT Clinical","Osteopathically distinctive end-of-rotation subject exams.","120 items, 2.5 hours; includes OPP/OMM. Subjects include EM, FM, IM, OB/GYN, OPP, Peds, Psychiatry, Surgery.","https://www.nbome.org/assessments/comat/clinical-subject-exams/"],["USMLE Step 2 CK","Clinical knowledge for supervised patient care.","Since May 7, 2026: 16 x 30-minute blocks; up to 318 items; 9-hour session. Passing standard 218 (since July 1, 2025).","https://www.usmle.org/step-exams/step-2-ck"],["COMLEX-USA Level 2-CE","Clinical + foundational science + osteopathic competencies.","2026 format: 320 single-best-answer items in one 8-hour testing day; numeric passing score 400.","https://www.nbome.org/assessments/comlex-usa/examination-format/"],["USMLE Step 3","Independent general medical care.","Two-day exam with MCQ + CCS cases; final USMLE licensure exam.","https://www.usmle.org/step-exams/step-3/step-3-exam-content"],["COMLEX-USA Level 3","Unsupervised osteopathic practice.","NBOME changes Level 3 to a one-day exam effective Jan 13, 2027: 240 MCQs + 16 CDM cases; passing score 350.","https://www.nbome.org/assessments/comlex-usa/examination-format/"]]},{"heading":"Assessment ladder","type":"bullets","items":["Preclinical: school exams -> mixed board-style blocks -> NBME CBSSA / official sample experience -> Step 1.","DO preclinical: school exams + OMM/OPP -> COMLEX-focused bank + NBOME practice -> Level 1; USMLE Step 1 can be layered when desired.","Clerkships: daily patient learning + Qbank -> NBME CSMS or COMAT-SE -> school shelf/COMAT -> cumulative Step 2/Level 2 prep.","Advanced clinical/residency: independent-management reasoning -> Step 3 CCS / COMLEX Level 3 CDM cases."]}],"page":4},{"name":"CORE RESOURCE STACK","list_label":"CORE RESOURCE STACK","phase":"","category":"Program Overview","sections":[{"heading":"","type":"table","columns":["Resource","Category","Best use","Link"],"rows":[["Official blueprints & sample software","USMLE + NBOME","Always start here. Defines current content, format and practice experience.","https://www.usmle.org/exam-resources"],["External readiness assessment","NBME","CBSSA for Step 1; CCSSA for Step 2; CSMS for clerkship subject exams.","https://www.nbme.org/examinees/self-assessments/"],["Primary question bank","UWorld","Deep answer explanations + exam-like clinical vignettes. Use longitudinally and during dedicated.","https://medical.uworld.com/usmle/"],["Integrated library + Qbank","AMBOSS","Useful for school blocks, clerkships, quick clinical reference and targeted questions.","https://www.amboss.com/us/students/student-life"],["Osteopathic question bank","TrueLearn / COMBANK","COMLEX/COMAT-specific questions and OMM emphasis; useful for DO students.","https://truelearn.com/comlex-usa/"],["Pathology video core","Pathoma","Mechanism-focused pathology review; 35+ hours of videos covering the text.","https://www.pathoma.com/"],["Clinical video core","OnlineMedEd","Clinical reasoning and rotation/Step 2 content across IM, Surgery, Peds, OB/GYN, Psych, Neuro and OMM.","https://www.onlinemeded.com/clinical"],["Bedside exam video core","Stanford Medicine 25","Physical-exam demonstrations and bedside technique.","https://stanfordmedicine25.stanford.edu/videos.html"],["Deep foundational videos","Ninja Nerd","Long-form explanatory teaching. Use selectively for difficult mechanisms rather than trying to watch everything.","https://www.youtube.com/watch?v=JDpg2tdHdq0"],["Spaced repetition","Anki / school deck","Use after understanding; prioritize cards tied to current block/Qbank misses. Avoid flashcard volume becoming the goal.",""],["Review index","First Aid for USMLE Step 1","Use as a concise index/checklist during systems blocks and dedicated; not as a standalone teaching source.",""]]},{"heading":"RESOURCE PRINCIPLE","type":"paragraph","text":"One strong explanatory source + one primary Qbank + official assessments beats collecting five overlapping resources. Add a second source only to solve a specific weakness."}],"page":5},{"name":"YEAR 1 - FOUNDATIONS OF MEDICINE","list_label":"YEAR 1 - FOUNDATIONS OF MEDICINE","phase":"","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"Goal: build the scientific language and clinical habits needed to understand disease rather than memorize disconnected facts.","type":"table","columns":["Course","Core scope"],"rows":[["Anatomy / Histology / Embryology","Structure, spatial relationships, imaging, tissue architecture, development and congenital anomalies."],["Cell & Molecular Biology + Genetics","Cell structure/function, DNA/RNA, gene expression, inheritance, genomics and molecular disease."],["Biochemistry & Metabolism","Macromolecules, enzymes, pathways, energy metabolism, vitamins, nutrition and metabolic disease."],["Physiology","Homeostasis, membrane physiology and integrated organ-system function."],["Immunology","Innate/adaptive immunity, hypersensitivity, autoimmunity, immunodeficiency, transplantation and immunotherapy principles."],["Microbiology","Bacteria, viruses, fungi, parasites, antimicrobial principles and host-pathogen relationships."],["Pharmacology Foundations","PK/PD, receptors, dose-response, adverse effects, interactions and prescribing logic."],["Pathology Foundations","Cell injury, inflammation, repair, hemodynamics, neoplasia and general disease mechanisms."],["Neuroscience + Behavioral Science","Neuroanatomy, signaling, sensation/motor systems, cognition, behavior and psychiatric foundations."],["Biostatistics / Epidemiology / EBM","Study design, bias, screening, diagnostic test performance, risk measures and literature interpretation."],["Clinical Skills I","History, physical exam, oral presentation, documentation, communication and basic procedures."],["Ethics / Professionalism / Health Systems","Consent, confidentiality, safety, systems-based care and professional identity."],["OPP / OMM - DO track","Osteopathic principles, structural exam, somatic dysfunction and foundational treatment techniques."]]},{"heading":"Goal: build the scientific language and clinical habits needed to understand disease rather than memorize disconnected facts. — Year 1 performance target","type":"bullets","items":["Explain mechanisms aloud without notes; draw major pathways and anatomy from memory.","Use foundational science to explain a patient vignette, not just recite isolated facts.","Complete board-style questions in parallel with each school block beginning early in the year.","Build a cumulative spaced-review system so foundational material remains retrievable when organ systems begin."]}],"page":6},{"name":"ANATOMY, HISTOLOGY & EMBRYOLOGY","list_label":"ANATOMY, HISTOLOGY & EMBRYOLOGY","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build 3D structural understanding, tissue recognition and developmental reasoning that can be applied to imaging, procedures, neurologic localization and congenital disease."},{"heading":"Mastery checklist","type":"bullets","items":["Anatomic terminology, planes and relationships; thorax, abdomen, pelvis/perineum, head/neck, limbs and back.","Neurovascular supply, dermatomes, lymphatics and clinically important spaces.","Histology of epithelium, connective tissue, muscle, nerve, vessels and major organs.","Embryologic weeks 1-8, folding, germ-layer derivatives, neurulation, cardiac/gut/urogenital development and congenital anomalies.","Cross-sectional anatomy and basic CT/MRI/radiograph orientation."]},{"heading":"You should be able to...","type":"bullets","items":["Localize a lesion from anatomy and symptoms.","Predict deficits from nerve, vessel or compartment injury.","Recognize major tissues and correlate microscopic structure with function.","Explain congenital anomalies from disrupted developmental steps.","Translate anatomy into physical-exam and procedural landmarks."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Ninja Nerd - Gastrulation","Video","https://www.youtube.com/watch?v=7SK-WPnF1Dc","Long-form embryology mechanism review."],["Stanford Medicine 25 - Video Gallery","Clinical video","https://stanfordmedicine25.stanford.edu/videos.html","Connect surface anatomy to bedside examination."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Anatomy, histology and imaging questions tied to systems."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Clinical-vignette anatomy and embryology application."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["USMLE Step 1 explicitly includes gross anatomy/embryology (10-20% discipline overlap) and histology/cell biology (5-15% overlap).","COMLEX Level 1 integrates anatomy within clinical presentations and OPP/OMM.","School anatomy practicals require image/cadaver/structure identification beyond board-question practice."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["After each region: closed-book structure sketch -> practical images -> 20-40 board-style questions.","Maintain an \"anatomy errors\" deck containing only relationships you actually miss.","Before a practical: mixed stations + radiology cross-sections + timed identification."]}],"page":7},{"name":"CELL & MOLECULAR BIOLOGY + GENETICS","list_label":"CELL & MOLECULAR BIOLOGY + GENETICS","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Create the mechanistic bridge from DNA and cell biology to inherited disease, cancer biology, targeted therapies and modern diagnostics."},{"heading":"Mastery checklist","type":"bullets","items":["Cell membranes, organelles, cytoskeleton, trafficking, signaling and cell cycle.","DNA replication/repair, transcription, RNA processing and translation.","Mendelian inheritance, pedigrees, penetrance/expressivity, mosaicism, imprinting and anticipation.","Chromosomal disease, population genetics and multifactorial inheritance.","Genomic technologies: PCR, sequencing, microarrays, cytogenetics and molecular diagnostics.","Cancer genetics, oncogenes, tumor suppressors and DNA-repair syndromes."]},{"heading":"You should be able to...","type":"bullets","items":["Predict phenotypes from inheritance patterns.","Interpret pedigrees, molecular test results and chromosome abnormalities.","Link cellular defects to organ-level disease.","Explain how mutations alter proteins, pathways and therapies.","Choose an appropriate molecular/genetic diagnostic approach at a conceptual level."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Johns Hopkins - Scientific Foundations of Medicine","University curriculum","https://www.hopkinsmedicine.org/som/curriculum/genes-to-society/year-one/scientific-foundations-medicine","Reference benchmark for molecular/cellular/genetic foundations."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Genetics and molecular disease review with board-style questions."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Apply molecular/genetic mechanisms to clinical vignettes."],["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Use discipline and organ-system mapping to check completeness."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["USMLE Step 1 lists genetics (5-10%) and histology/cell biology (5-15%) as overlapping disciplines.","Genetics also reappears in pediatrics, obstetrics, oncology, neurology and reproductive medicine throughout later years."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Solve pedigrees and probability questions without notes.","For each genetic disease, learn inheritance + molecular defect + mechanism + major phenotype + diagnostic clue.","Use mixed questions so genetics is not learned as an isolated discipline."]}],"page":8},{"name":"BIOCHEMISTRY & METABOLISM","list_label":"BIOCHEMISTRY & METABOLISM","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Understand energy handling and macromolecular metabolism well enough to reason through nutrition, endocrine disease, inborn errors, toxicology and pharmacologic effects."},{"heading":"Mastery checklist","type":"bullets","items":["Protein structure, enzymes, kinetics and regulation.","Glycolysis, gluconeogenesis, glycogen, TCA, oxidative phosphorylation and pentose phosphate pathway.","Fatty-acid metabolism, ketones, cholesterol/lipoproteins.","Amino-acid and nitrogen metabolism, urea cycle, heme metabolism and purines/pyrimidines.","Fed/fasted states, insulin/glucagon integration and exercise metabolism.","Vitamins/cofactors, nutrition and common inborn errors of metabolism."]},{"heading":"You should be able to...","type":"bullets","items":["Draw central pathways from memory and identify regulated steps.","Predict laboratory findings from enzyme deficiencies.","Integrate metabolism with endocrine physiology and nutrition.","Explain vitamin/cofactor deficiency syndromes mechanistically.","Use biochemical mechanisms to interpret drug/toxin effects."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Johns Hopkins - Scientific Foundations of Medicine","University benchmark","https://www.hopkinsmedicine.org/som/curriculum/genes-to-society/year-one/scientific-foundations-medicine","Includes macromolecules, metabolism and genetics as core foundations."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Clinical biochemistry + metabolic disease vignettes."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Targeted metabolism/nutrition review and questions."],["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Step 1 discipline weighting includes biochemistry (5-15%) and nutrition integrated across systems."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Step 1 foundational science remains integrated into organ-system disease rather than isolated recall.","COMLEX Level 1 similarly tests biomedical science in clinical presentations."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["At end of each pathway: reproduce pathway + regulation + key diseases on one page.","Use cases such as fasting hypoglycemia, acidosis, hyperammonemia and dyslipidemia to force integration.","Repeat missed metabolic questions after 7-14 days to confirm durable correction."]}],"page":9},{"name":"PHYSIOLOGY","list_label":"PHYSIOLOGY","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build quantitative and mechanistic understanding of normal function so pathology becomes a deviation from a known model rather than a list of facts."},{"heading":"Mastery checklist","type":"bullets","items":["Membrane potentials, ion channels, transport and action potentials.","Autonomic physiology, receptor signaling and second messengers.","Cardiac mechanics, pressure-volume relationships and hemodynamics.","Respiratory mechanics, gas exchange and acid-base.","Renal filtration, tubular transport, volume/osmolality and acid-base.","GI, endocrine and reproductive physiology.","Exercise, thermoregulation and integrated homeostasis."]},{"heading":"You should be able to...","type":"bullets","items":["Predict direction-of-change in physiologic variables.","Interpret basic pressure-volume, flow, gas and renal graphs.","Solve acid-base and clearance concepts.","Explain compensatory responses to perturbation.","Use normal physiology to infer pathology and therapy."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Ninja Nerd - Pharmacodynamics","Deep mechanism video","https://www.youtube.com/watch?v=JDpg2tdHdq0","Although pharmacology-focused, it reinforces receptors, dose-response and physiologic signaling."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","High-value integrated physiology questions."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","System-based physiology review and diagrams."],["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Physiology overlaps roughly 30-40% of Step 1 items by discipline classification."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Physiology is one of the largest Step 1 discipline overlaps.","Every Year 2 organ-system block should reopen the relevant normal-physiology model before pathology."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Build equation/relationship sheets from memory rather than copying formulas.","Explain each graph out loud and predict what changes under disease/drug perturbation.","Do system-mixed questions weekly to prevent compartmentalized learning."]}],"page":10},{"name":"IMMUNOLOGY","list_label":"IMMUNOLOGY","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Understand immune mechanisms well enough to reason through infection, autoimmunity, allergy, immunodeficiency, transplantation and immunomodulatory therapy."},{"heading":"Mastery checklist","type":"bullets","items":["Innate immunity, barriers, complement, phagocytes and inflammation.","Antigen presentation, T/B-cell development and activation, antibodies and class switching.","Cytokines and immune signaling.","Hypersensitivity I-IV.","Primary/secondary immunodeficiency.","Autoimmunity and tolerance.","Transplantation, tumor immunity and biologic therapies."]},{"heading":"You should be able to...","type":"bullets","items":["Predict which immune arm is defective from infection patterns.","Explain hypersensitivity and autoimmune disease mechanisms.","Connect cytokine/receptor targets to immunotherapies.","Interpret basic serologic and immunologic testing.","Integrate immunity with microbiology, pathology and pharmacology."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Ninja Nerd - Inflammation: Vascular Events","Video","https://www.youtube.com/watch?v=LArxUakFsFs","Detailed mechanism-oriented inflammation teaching."],["Pathoma","Pathology video core","https://www.pathoma.com/","Reinforces inflammation, immune disease and neoplasia."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Clinical immunology vignettes."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Immunodeficiency, hypersensitivity and autoimmune review."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["USMLE Step 1 includes immunology overlap (5-15%) and blood/lymphoreticular/immune systems (9-13%).","COMLEX also integrates immunity within systemic presentations."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Create mechanism maps for complement, T-cell/B-cell activation and hypersensitivity.","For each immunodeficiency: defect -> infection pattern -> key labs -> treatment principle.","Interleave immune questions with infectious disease and hematology."]}],"page":11},{"name":"MICROBIOLOGY & INFECTIOUS DISEASE FOUNDATIONS","list_label":"MICROBIOLOGY & INFECTIOUS DISEASE FOUNDATIONS","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build a clinically organized mental model of pathogens, virulence, transmission, diagnostics and antimicrobial targets."},{"heading":"Mastery checklist","type":"bullets","items":["Bacterial structure, Gram staining, toxins, virulence and major organisms by morphology/site.","Viral structure, replication, latency and major virus families.","Fungi and parasites.","Sterilization/disinfection, epidemiology and infection control.","Diagnostic microbiology: stain/culture, antigen, PCR and serology concepts.","Antimicrobial mechanisms and resistance principles."]},{"heading":"You should be able to...","type":"bullets","items":["Identify likely pathogens from host + exposure + syndrome.","Choose a conceptual diagnostic test based on organism biology.","Explain antibiotic target and resistance mechanism.","Connect microbiology to immune status and organ system.","Recognize infection-control and prevention principles."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Ninja Nerd - Bacteria: Structure and Function","Video","https://www.youtube.com/watch?v=ayFiGn2fYi8","Long-form bacterial foundations, Gram structure and classification."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Syndrome-based microbiology application."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Organism and infectious-disease lookup + questions."],["Pathoma","Pathology integration","https://www.pathoma.com/","Useful for inflammatory responses and infection-related pathology."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Step 1 microbiology overlap is 10-20% by discipline classification.","Clinical microbiology is heavily revisited in Year 2 ID and Year 3 medicine/pediatrics/OB/GYN."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Learn organisms by syndrome and differentiating features, not alphabetically.","For each antimicrobial family: mechanism -> major uses -> signature toxicity -> resistance.","Weekly mixed infection blocks including micro + immunology + pharmacology."]}],"page":12},{"name":"PHARMACOLOGY FOUNDATIONS","list_label":"PHARMACOLOGY FOUNDATIONS","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build a durable framework for drug action, dosing logic, interactions and toxicity before memorizing system-specific agents."},{"heading":"Mastery checklist","type":"bullets","items":["Pharmacokinetics: absorption, distribution, metabolism, elimination, clearance, half-life, steady state.","Pharmacodynamics: receptors, agonists/antagonists, potency, efficacy, dose-response and therapeutic index.","Drug metabolism and CYP interactions.","Adverse drug reactions, contraindications and therapeutic monitoring.","Autonomic pharmacology foundations.","Principles of safe prescribing and medication reconciliation."]},{"heading":"You should be able to...","type":"bullets","items":["Interpret dose-response curves and PK relationships.","Predict interaction and toxicity patterns.","Distinguish potency from efficacy and competitive from noncompetitive effects.","Explain why renal/hepatic dysfunction changes dosing.","Use mechanisms to learn later drug classes efficiently."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Ninja Nerd - Pharmacodynamics","Video","https://www.youtube.com/watch?v=JDpg2tdHdq0","~90-minute mechanism-rich pharmacodynamics lecture with practice problems."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Mechanism and adverse-effect application."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Drug class review and clinical context."],["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Pharmacology overlaps roughly 10-20% of Step 1 items by discipline classification."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Step 1 tests pharmacology primarily in disease/system context.","Step 2/clinical years shift toward treatment selection, adverse effects and management decisions."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Create drug-class cards organized by mechanism, not brand names.","Complete calculation/curve questions until they are fast and automatic.","Add every Qbank drug error to a running \"mechanism-use-toxicity\" table."]}],"page":13},{"name":"PATHOLOGY FOUNDATIONS","list_label":"PATHOLOGY FOUNDATIONS","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Learn the universal mechanisms of injury and disease that repeat across every organ system."},{"heading":"Mastery checklist","type":"bullets","items":["Cell injury, adaptation and death.","Acute/chronic inflammation and mediators.","Repair, regeneration, fibrosis and wound healing.","Hemodynamic disorders: edema, thrombosis, embolism, infarction and shock.","Neoplasia: hallmarks, grading/staging, carcinogenesis and metastasis.","Environmental/nutritional disease and selected genetic mechanisms."]},{"heading":"You should be able to...","type":"bullets","items":["Explain a disease process from cause to cellular injury to clinical manifestation.","Differentiate acute vs chronic inflammation and predict complications.","Reason through thrombosis/shock using mechanisms.","Explain neoplastic transformation and spread.","Recognize classic gross/microscopic patterns conceptually."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Pathoma","Primary pathology video/text","https://www.pathoma.com/","35+ hours covering general + organ-system pathology; highly useful across preclinical years."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Pathology integrated with physiology and pharmacology."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Clinical pathology review and images."],["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Pathology is the largest Step 1 discipline overlap (45-55%)."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["General pathology should be mastered before organ-system pathology.","Pathology remains central to Step 1 and becomes diagnostic/management context on Step 2."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["After each Pathoma chapter: closed-book summary + 20-40 targeted questions.","Build image recognition from school slides, pathology labs and Qbank images.","Use mechanism-first explanations for every wrong answer."]}],"page":14},{"name":"NEUROSCIENCE + BEHAVIORAL SCIENCE","list_label":"NEUROSCIENCE + BEHAVIORAL SCIENCE","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build localization, neurophysiology and behavioral foundations that support neurology, psychiatry and sensory-system disease."},{"heading":"Mastery checklist","type":"bullets","items":["Neuroanatomy: tracts, brainstem, cortex, cerebellum, basal ganglia, spinal cord and vascular territories.","Neurophysiology, neurotransmitters and synaptic signaling.","Special senses.","Motor and sensory localization.","Sleep, cognition, learning, development and behavior.","Psychiatric diagnostic foundations and behavioral science principles."]},{"heading":"You should be able to...","type":"bullets","items":["Localize lesions from symptoms and exam findings.","Predict deficits from tract/vascular lesions.","Connect neurotransmitters to medications and disease.","Distinguish basic psychiatric syndromes.","Perform and interpret a focused neurologic/mental-status exam."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Stanford Medicine 25 - Cerebellar Exam","Video","https://www.youtube.com/watch?v=Imu1kk_gOKA","Bedside cerebellar examination demonstration."],["Stanford Medicine 25 - Video Gallery","Clinical video library","https://stanfordmedicine25.stanford.edu/videos.html","Neurologic, gait, reflex and movement examination videos."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Neuroanatomy localization + neuropharmacology questions."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Neurology/psychiatry mechanisms and clinical context."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Step 1 combines behavioral health + nervous systems/special senses at 10-14%.","Clinical neurology and psychiatry later have dedicated shelf/COMAT pathways."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Draw major tracts and brainstem relationships repeatedly from memory.","Practice localization before naming a disease.","Pair every neuroanatomy block with physical-exam videos and cases."]}],"page":15},{"name":"BIOSTATISTICS, EPIDEMIOLOGY & EVIDENCE-BASED MEDICINE","list_label":"BIOSTATISTICS, EPIDEMIOLOGY & EVIDENCE-BASED MEDICINE","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Become fluent enough in quantitative reasoning to interpret studies, screening tests and clinical evidence under time pressure."},{"heading":"Mastery checklist","type":"bullets","items":["Study designs, hierarchy of evidence and causal inference basics.","Bias, confounding, effect modification and validity.","Risk, odds, incidence, prevalence, relative/absolute risk, NNT/NNH.","Sensitivity, specificity, predictive values and likelihood concepts.","Confidence intervals, p-values, power and common statistical tests conceptually.","Diagnostic studies, screening, systematic reviews and guideline interpretation."]},{"heading":"You should be able to...","type":"bullets","items":["Identify study design and major threats to validity.","Calculate and interpret core epidemiologic measures.","Interpret screening/diagnostic test results in context of prevalence.","Read abstracts, tables and forest plots efficiently.","Translate evidence into a patient-centered decision."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["USMLE Step 1 content outline","Official blueprint","https://www.usmle.org/exam-resources/step-1-materials/step-1-content-outline-and-specifications","Biostatistics/epidemiology/population health 4-6% of Step 1."],["USMLE Step 2 CK content outline","Official blueprint","https://www.usmle.org/exam-resources/step-2-ck-materials/step-2-ck-content-outline-specifications","Biostatistics/epidemiology/literature interpretation 3-5% on Step 2 CK."],["UWorld Step 1","Qbank","https://medical.uworld.com/usmle/usmle-step-1/","Repeated quantitative application and abstract interpretation."],["AMBOSS","Library + Qbank","https://www.amboss.com/us/students/student-life","Targeted EBM and biostatistics review."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["Biostatistics and evidence interpretation persist across Step 1, Step 2 and Step 3.","Do not leave this domain for dedicated; fluency comes from repeated small doses."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Do a short statistics block every week.","Maintain a one-page formula/interpretation sheet built from errors.","Practice full abstracts under timed conditions before Step 2/3."]}],"page":16},{"name":"CLINICAL SKILLS I + PROFESSIONAL PRACTICE","list_label":"CLINICAL SKILLS I + PROFESSIONAL PRACTICE","phase":"YEAR 1 - FOUNDATIONS | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Begin behaving like a clinician from the first year: gather data accurately, examine the patient, communicate clearly and work safely within the healthcare system."},{"heading":"Mastery checklist","type":"bullets","items":["Patient-centered interview, agenda setting and history of present illness.","Medication/allergy/social/family history and preventive care.","Vital signs and general survey.","Cardiac, pulmonary, abdominal, neurologic, musculoskeletal, skin and basic HEENT exams.","Oral case presentation and note structure.","Communication, informed consent, confidentiality, error disclosure and teamwork.","Basic patient safety, hand hygiene and infection prevention."]},{"heading":"You should be able to...","type":"bullets","items":["Obtain a focused and complete history.","Perform and verbalize the logic of a basic physical exam.","Present a patient in a concise problem-oriented format.","Write a structured note and problem list.","Recognize when supervision/escalation is required."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["Stanford Medicine 25 - Introduction","Video","https://www.youtube.com/watch?v=e5_Wim4exoM","Why and how to learn bedside physical examination."],["Stanford Medicine 25 - Video Gallery","Clinical videos","https://stanfordmedicine25.stanford.edu/videos.html","High-quality focused physical exam demonstrations."],["AAMC Core EPAs","Competency framework","https://www.aamc.org/about-us/mission-areas/medical-education/cbme/core-epas","Use as a longitudinal clinical-performance destination."],["AMBOSS Clerkship Guide","Clinical reference","https://www.amboss.com/us/knowledge/clerkship-guide","Helpful later for presentations, notes and workflow; preview now."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["School OSCEs/standardized-patient assessments are the primary early clinical-skills exams.","USMLE Step 1 includes communication/interpersonal skills; Step 2/3 expand patient-care decision making."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Practice with a partner or standardized patient, not only videos.","Use a checklist initially, then perform from memory and explain each maneuver.","Record short oral presentations and self-audit for structure, accuracy and prioritization."]}],"page":17},{"name":"OSTEOPATHIC PRINCIPLES & MANIPULATIVE MEDICINE (DO TRACK)","list_label":"OSTEOPATHIC PRINCIPLES & MANIPULATIVE MEDICINE (DO TRACK)","phase":"YEAR 1-2 LONGITUDINAL | Curriculum + Exam Mastery","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"WHY THIS COURSE EXISTS","type":"paragraph","text":"Build the osteopathic-specific competency layer required for DO school performance, COMLEX and COMAT, while keeping structural diagnosis and treatment clinically grounded."},{"heading":"Mastery checklist","type":"bullets","items":["Osteopathic philosophy and tenets.","Structural examination and somatic dysfunction.","Biomechanics of spine, ribs, pelvis and extremities.","Muscle energy, HVLA, counterstrain, myofascial release and other foundational techniques as taught by the school.","Autonomic relationships and viscerosomatic concepts.","Contraindications, safety and integration with conventional diagnosis/treatment."]},{"heading":"You should be able to...","type":"bullets","items":["Perform a supervised structural exam and document findings.","Diagnose common somatic dysfunction patterns using school-taught models.","Choose a reasonable OMT technique and recognize contraindications.","Integrate OPP/OMM with a clinical vignette rather than treating it as isolated memorization."]},{"heading":"High-value learning resources","type":"table","columns":["Resource","Type","Link","How to use it"],"rows":[["NBOME COMLEX Blueprint","Official blueprint","https://www.nbome.org/assessments/comlex-usa/comlex-usa-blueprint/","Defines osteopathic competency domains and clinical presentations."],["TrueLearn COMLEX","COMLEX-specific Qbank","https://truelearn.com/comlex-usa/","COMLEX-formatted questions and OMM-focused material."],["UWorld COMLEX","Qbank","https://medical.uworld.com/comlex/","Step/COMLEX integrated question practice including OMT items."],["PNWU-COM Curriculum","DO benchmark","https://www.pnwu.edu/academics/college-of-osteopathic-medicine/curriculum/","Example of longitudinal OPP/OMM within a four-year DO curriculum."]]},{"heading":"High-value learning resources — Exam alignment","type":"bullets","items":["COMLEX Level 1 and Level 2-CE integrate osteopathic principles and practice throughout the blueprint.","COMAT clinical exams include OPP/OMM within discipline-specific patient scenarios."]},{"heading":"High-value learning resources — Mastery / assessment loop","type":"bullets","items":["Skills must be practiced in lab under qualified supervision.","Pair each technique family with indications + contraindications + structural diagnosis.","Use COMLEX-style questions weekly so OPP remains integrated with systems."]}],"page":18},{"name":"YEAR 1 - EXAM MASTERY PLAN","list_label":"YEAR 1 - EXAM MASTERY PLAN","phase":"","category":"Year 1 — Foundations of Medicine","sections":[{"heading":"","type":"table","columns":["Timing","What to do","Evidence of readiness"],"rows":[["During each block","School objectives first; same-day retrieval; 10-20 targeted board-style questions after concepts are learned.","Can explain mechanisms without notes; rising school quiz scores; error log shrinking."],["Weekly","One cumulative mixed block + spaced review of prior systems/foundations.","Old material remains retrievable; fewer \"I knew this last month\" misses."],["End of block","Timed mixed questions + practical/OSCE as applicable + written remediation plan.","Can transfer knowledge to novel vignettes, images and clinical skills."],["End of Year 1","Cumulative foundational review and baseline external-style assessment when school permits.","Clear system/discipline strengths and weaknesses before Year 2."]]},{"heading":"DO NOT OVER-BOARD-PREP YEAR 1","type":"paragraph","text":"The goal is not to enter dedicated early. The goal is to learn every school block deeply enough that later Step 1/COMLEX review becomes retrieval and integration rather than first exposure."}],"page":19},{"name":"YEAR 2 - ORGAN SYSTEMS, DISEASE & THERAPEUTICS","list_label":"YEAR 2 - ORGAN SYSTEMS, DISEASE & THERAPEUTICS","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"Goal: integrate normal physiology with pathology, microbiology, pharmacology, diagnostics and treatment decisions.","type":"table","columns":["Block","Scope"],"rows":[["Cardiovascular","Hemodynamics, ischemic disease, heart failure, valves, arrhythmia, congenital disease, vascular disease, cardiovascular drugs."],["Respiratory","Mechanics/gas exchange, obstructive/restrictive disease, pneumonia, pulmonary vascular disease, neoplasia, respiratory drugs."],["Renal / Urinary","Filtration/tubules, fluids/electrolytes, acid-base, AKI/CKD, glomerular disease, nephritic/nephrotic syndromes, diuretics."],["GI / Liver / Nutrition","Motility/absorption, GI pathology, liver/pancreas/biliary disease, nutrition and GI pharmacology."],["Endocrine / Metabolism","Pituitary, thyroid, adrenal, diabetes, calcium/bone, endocrine pharmacology."],["Reproductive / Pregnancy Foundations","Male/female reproductive disease, fertility, pregnancy physiology/pathology, breast disease, reproductive pharmacology."],["Hematology / Oncology","Anemia, bleeding/clotting, leukemias/lymphomas, oncologic principles and therapeutics."],["Infectious Disease","Syndrome-based infections, antimicrobial selection/resistance and infection prevention."],["MSK / Rheumatology / Dermatology","Arthritis, autoimmune disease, bone/muscle pathology, dermatologic patterns and related therapies."],["Neurology / Psychiatry","Localization + neurologic disease, psychiatric diagnosis and psychopharmacology."],["Integrated Clinical Reasoning","Differential diagnosis, test selection, pretest probability, management sequencing and safety."]]}],"page":20},{"name":"YEAR 2 SYSTEM BLOCKS","list_label":"Year 2 System Blocks — Cardiovascular & Respiratory","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"CARDIOVASCULAR — Core checklist","type":"bullets","items":["Cardiac anatomy + conduction; pressure-volume loops; preload/afterload/contractility.","Ischemic disease, heart failure, valves, cardiomyopathy, arrhythmias, congenital lesions, hypertension and vascular disease.","ECG foundations, murmurs/hemodynamics, cardiac imaging concepts.","Antianginal, antihypertensive, antiarrhythmic, HF and anticoagulant pharmacology."]},{"heading":"CARDIOVASCULAR — Mastery outcomes","type":"bullets","items":["Explain murmurs and hemodynamic changes.","Interpret common ECG patterns at a foundational level.","Select diagnostic next steps and mechanism-based therapy in vignettes. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"RESPIRATORY — Core checklist","type":"bullets","items":["Ventilation/perfusion, diffusion, compliance, oxygen transport and acid-base.","Asthma/COPD, restrictive disease, pneumonia, pleural disease, pulmonary hypertension/embolism, ARDS, lung cancer.","PFTs, ABGs, imaging patterns.","Bronchodilators, steroids, antibiotics and pulmonary vascular therapies."]},{"heading":"RESPIRATORY — Mastery outcomes","type":"bullets","items":["Interpret PFT/ABG patterns.","Use physiology to distinguish hypoxemia mechanisms.","Connect respiratory drugs to disease mechanism and adverse effects. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"SYSTEM BLOCK ASSESSMENT","type":"paragraph","text":"Complete a targeted question set after each major topic, then a timed mixed block at the end of the system. Remediate by mechanism, not by memorizing the question."}],"page":21},{"name":"YEAR 2 SYSTEM BLOCKS","list_label":"Year 2 System Blocks — Renal / Urinary & Gi / Liver / Nutrition","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"RENAL / URINARY — Core checklist","type":"bullets","items":["GFR, autoregulation, tubular handling, osmolality and acid-base.","AKI/CKD, glomerular disease, nephritic/nephrotic syndromes, stones and urinary tract disease.","Electrolyte disorders and volume states.","Diuretics, RAAS agents and renal dosing principles."]},{"heading":"RENAL / URINARY — Mastery outcomes","type":"bullets","items":["Localize renal pathology from labs/urinalysis.","Solve acid-base/electrolyte problems.","Predict diuretic effects and complications. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"GI / LIVER / NUTRITION — Core checklist","type":"bullets","items":["GI motility, digestion/absorption and hepatic physiology.","Esophageal, gastric, intestinal, pancreatic, biliary and liver disease.","Malabsorption, inflammatory bowel disease, GI bleeding and GI cancers.","Nutrition, vitamins and GI pharmacology."]},{"heading":"GI / LIVER / NUTRITION — Mastery outcomes","type":"bullets","items":["Localize GI disease by symptom pattern.","Interpret liver tests and common GI workups.","Integrate nutrition and medication mechanisms. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"SYSTEM BLOCK ASSESSMENT","type":"paragraph","text":"Complete a targeted question set after each major topic, then a timed mixed block at the end of the system. Remediate by mechanism, not by memorizing the question."}],"page":22},{"name":"YEAR 2 SYSTEM BLOCKS","list_label":"Year 2 System Blocks — Endocrine / Metabolism & Reproductive + Pregnancy Foundations","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"ENDOCRINE / METABOLISM — Core checklist","type":"bullets","items":["Hypothalamic-pituitary axes and feedback.","Thyroid, adrenal, diabetes, calcium/parathyroid and bone disease.","Endocrine tumors and endocrine emergencies.","Insulin, oral diabetes drugs, thyroid, steroid and bone pharmacology."]},{"heading":"ENDOCRINE / METABOLISM — Mastery outcomes","type":"bullets","items":["Interpret hormone patterns.","Recognize endocrine emergencies.","Choose mechanism-based therapy and monitoring. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"REPRODUCTIVE + PREGNANCY FOUNDATIONS — Core checklist","type":"bullets","items":["Male/female reproductive physiology and pathology.","Menstrual cycle, fertility and contraception.","Pregnancy physiology, early/late pregnancy complications and fetal development.","Breast pathology and reproductive cancers."]},{"heading":"REPRODUCTIVE + PREGNANCY FOUNDATIONS — Mastery outcomes","type":"bullets","items":["Reason through abnormal bleeding/infertility.","Recognize common pregnancy pathophysiology.","Integrate embryology with congenital/reproductive disease. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"SYSTEM BLOCK ASSESSMENT","type":"paragraph","text":"Complete a targeted question set after each major topic, then a timed mixed block at the end of the system. Remediate by mechanism, not by memorizing the question."}],"page":23},{"name":"YEAR 2 SYSTEM BLOCKS","list_label":"Year 2 System Blocks — Hematology / Oncology & Infectious Disease","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"HEMATOLOGY / ONCOLOGY — Core checklist","type":"bullets","items":["Hematopoiesis, anemia classification and hemolysis.","Platelets/coagulation and thrombosis.","Leukemia, lymphoma, plasma-cell disorders.","Cancer biology, staging principles, chemotherapy/toxicities and oncologic emergencies."]},{"heading":"HEMATOLOGY / ONCOLOGY — Mastery outcomes","type":"bullets","items":["Interpret CBC/smear/coagulation patterns.","Classify anemia quickly.","Recognize oncologic emergencies and treatment toxicities. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"INFECTIOUS DISEASE — Core checklist","type":"bullets","items":["Syndrome-based bacterial, viral, fungal and parasitic disease.","Antimicrobial selection, resistance and stewardship.","HIV and opportunistic infection principles.","Vaccination, infection prevention and public-health response."]},{"heading":"INFECTIOUS DISEASE — Mastery outcomes","type":"bullets","items":["Choose likely pathogen and first diagnostic step.","Use antimicrobial mechanism + patient factors to guide therapy.","Recognize isolation/prevention principles. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"SYSTEM BLOCK ASSESSMENT","type":"paragraph","text":"Complete a targeted question set after each major topic, then a timed mixed block at the end of the system. Remediate by mechanism, not by memorizing the question."}],"page":24},{"name":"YEAR 2 SYSTEM BLOCKS","list_label":"Year 2 System Blocks — Msk / Rheum / Derm & Neurology / Psychiatry","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"MSK / RHEUM / DERM — Core checklist","type":"bullets","items":["Bone/joint/muscle physiology and pathology.","Inflammatory vs degenerative arthritis, connective-tissue disease and vasculitis.","Bone tumors/metabolic bone disease.","Dermatologic morphology, inflammatory disease, infection and malignancy."]},{"heading":"MSK / RHEUM / DERM — Mastery outcomes","type":"bullets","items":["Differentiate inflammatory from mechanical patterns.","Recognize common rash morphology and dangerous presentations.","Connect autoantibodies/pathophysiology to rheumatic disease. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"NEUROLOGY / PSYCHIATRY — Core checklist","type":"bullets","items":["Neuroanatomic localization and vascular syndromes.","Seizure, headache, movement, demyelinating, neuromuscular and neurodegenerative disease.","Mood, anxiety, psychotic, substance-use, personality and neurocognitive disorders.","Neurologic/psychiatric pharmacology and adverse effects."]},{"heading":"NEUROLOGY / PSYCHIATRY — Mastery outcomes","type":"bullets","items":["Localize before diagnosing.","Choose first-line diagnostic and management steps in common syndromes.","Differentiate medication adverse effects from disease progression. Use Pathoma for pathology, UWorld Step 1 or AMBOSS for vignette practice, and your school lectures for local objectives."]},{"heading":"SYSTEM BLOCK ASSESSMENT","type":"paragraph","text":"Complete a targeted question set after each major topic, then a timed mixed block at the end of the system. Remediate by mechanism, not by memorizing the question."}],"page":25},{"name":"YEAR 2 CAPSTONE - STEP 1 + COMLEX LEVEL 1","list_label":"YEAR 2 CAPSTONE - STEP 1 + COMLEX LEVEL 1","phase":"","category":"Year 2 — Systems & Disease","sections":[{"heading":"","type":"table","columns":["Domain","USMLE Step 1 current emphasis"],"rows":[["Foundational science competency","60-70% of items assess applying foundational science concepts."],["Pathology","45-55% discipline overlap."],["Physiology","30-40% overlap."],["Microbiology / Pharmacology","Each 10-20% overlap."],["Gross anatomy & embryology","10-20% overlap."],["Biochemistry / Histology / Immunology / Genetics","Each remains meaningfully represented and integrated."],["Systems","Largest grouped areas include Reproductive+Endocrine (12-16%), Respiratory+Renal (11-15%), Behavioral+Nervous (10-14%), Blood/Immune (9-13%)."]]},{"heading":"Dedicated study sequence","type":"table","columns":["Stage","Recommended execution"],"rows":[["Baseline","Take a school-required or external baseline; identify the 3-5 weakest systems/disciplines."],["First pass","Primary Qbank daily + targeted content repair. Avoid restarting every video course from the beginning."],["Cumulative practice","Timed mixed blocks under exam-like conditions; review every missed/guessed item."],["Readiness checks","NBME CBSSA forms for Step 1; official USMLE sample interface; for DO, NBOME/COMLEX-focused assessments + school requirements."],["Final week","Consolidate errors, formulas, ethics/biostats, weak systems; taper new content and protect sleep."]]},{"heading":"Dedicated study sequence — Board stack","type":"bullets","items":["UWorld Step 1 - primary learning Qbank.","NBME CBSSA - external readiness assessment for Step 1.","USMLE official materials - current exam format, content outline and interactive sample experience.","Pathoma - pathology consolidation.","AMBOSS - alternate/secondary Qbank + rapid reference.","DO: NBOME Blueprint + TrueLearn COMLEX or UWorld COMLEX for OPP/OMM and COMLEX-style practice."]}],"page":26},{"name":"YEAR 3 - CORE CLINICAL CLERKSHIPS","list_label":"YEAR 3 - CORE CLINICAL CLERKSHIPS","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"Goal: convert knowledge into safe, supervised patient care and standardized clinical-exam performance.","type":"table","columns":["Clerkship","Core competency"],"rows":[["Internal Medicine","History/exam, differential, diagnostics and management of common adult inpatient/outpatient disease; chronic disease; acute decompensation."],["Surgery","Pre/post-op care, surgical abdomen, trauma, fluids/electrolytes, wound/infection, common procedures and surgical decision making."],["Family Medicine","Preventive care, undifferentiated outpatient problems, chronic disease, pediatrics/women's health overlap and continuity."],["Pediatrics","Growth/development, preventive care, neonatal issues, common acute/chronic pediatric disease and pediatric emergencies."],["Obstetrics & Gynecology","Prenatal care, labor/delivery, pregnancy complications, gynecologic disease, contraception, cancer screening."],["Psychiatry","Diagnostic interviewing, risk assessment, mood/psychotic/anxiety/substance disorders, pharmacotherapy and disposition."],["Neurology","Localization, stroke, seizures, headache, movement, neuropathy, neuromuscular disease and neurologic emergencies."],["Emergency Medicine","Stabilization, resuscitation, undifferentiated complaints and disposition; core at some schools and Year 4 at others."],["OPP/OMM - DO","Apply osteopathic concepts/OMT appropriately within clinical rotations and COMAT/COMLEX preparation."]]},{"heading":"Goal: convert knowledge into safe, supervised patient care and standardized clinical-exam performance. — CLERKSHIP STUDY RULE","type":"paragraph","text":"Study from the patients you see, but do not study only the patients you see. Shelf/COMAT exams sample the full discipline, including topics your rotation may not expose you to."}],"page":27},{"name":"CLERKSHIP MASTERY","list_label":"Clerkship Mastery — Internal Medicine & Surgery","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"INTERNAL MEDICINE","type":"bullets","items":["Cardiology, pulmonary, GI, renal, endocrine, ID, hematology/oncology, rheumatology and inpatient medicine.","Problem representation, prioritized differential, test selection, acute management and chronic disease."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS medicine questions from day 1.","OnlineMedEd Internal Medicine for structured clinical framework.","NBME Medicine CSMS or COMAT-SE before the final exam. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"SURGERY","type":"bullets","items":["Pre-op assessment, postoperative complications, fluids/electrolytes, nutrition, trauma, abdominal disease and surgical emergencies.","Know indications/contraindications and when operative vs nonoperative management is appropriate."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS Surgery + selected Internal Medicine overlap.","OnlineMedEd Surgery for framework.","NBME Surgery CSMS / COMAT-SE + targeted anatomy review. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"CLINICAL PERFORMANCE","type":"paragraph","text":"For every patient: know the problem representation, differential, key evidence for/against, next diagnostic step, initial management, disposition and what could make the patient worse."}],"page":28},{"name":"CLERKSHIP MASTERY","list_label":"Clerkship Mastery — Pediatrics & Obstetrics & Gynecology","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"PEDIATRICS","type":"bullets","items":["Growth/development, newborn care, preventive pediatrics, infections, respiratory/GI/neuro/endocrine disease and pediatric emergencies."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS Pediatrics.","OnlineMedEd Pediatrics.","NBME Pediatrics CSMS / COMAT-SE; review growth/development and vaccines repeatedly. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"OBSTETRICS & GYNECOLOGY","type":"bullets","items":["Prenatal care, fetal assessment, labor, postpartum care, pregnancy complications, abnormal bleeding, pelvic pain, contraception, infertility and gynecologic oncology."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS OB/GYN.","OnlineMedEd OB/GYN.","NBME OB/GYN CSMS / COMAT-SE; practice management algorithms. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"CLINICAL PERFORMANCE","type":"paragraph","text":"For every patient: know the problem representation, differential, key evidence for/against, next diagnostic step, initial management, disposition and what could make the patient worse."}],"page":29},{"name":"CLERKSHIP MASTERY","list_label":"Clerkship Mastery — Psychiatry & Family Medicine","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"PSYCHIATRY","type":"bullets","items":["Mental-status exam, suicide/violence risk, mood, psychosis, anxiety, trauma, substance use, personality, child psych and medication effects."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS Psychiatry.","OnlineMedEd Psychiatry.","NBME Psychiatry CSMS / COMAT-SE; drill distinguishing features and drug adverse effects. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"FAMILY MEDICINE","type":"bullets","items":["Preventive guidelines, screening, outpatient chronic disease, common acute complaints, dermatology/MSK, women's health and pediatrics overlap."]},{"heading":"Exam + ward plan","type":"bullets","items":["AMBOSS Family Medicine study plan or equivalent.","UWorld ambulatory/family content.","NBME Family Medicine CSMS / COMAT-SE; emphasize prevention. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"CLINICAL PERFORMANCE","type":"paragraph","text":"For every patient: know the problem representation, differential, key evidence for/against, next diagnostic step, initial management, disposition and what could make the patient worse."}],"page":30},{"name":"CLERKSHIP MASTERY","list_label":"Clerkship Mastery — Neurology & Emergency Medicine","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"NEUROLOGY","type":"bullets","items":["Localization, stroke, seizure, headache, movement, demyelinating, neuromuscular and peripheral nerve disease."]},{"heading":"Exam + ward plan","type":"bullets","items":["UWorld/AMBOSS Neurology.","Stanford Medicine 25 for neurologic exam.","NBME Neurology CSMS; localization before disease labels. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"EMERGENCY MEDICINE","type":"bullets","items":["ABCs, resuscitation, shock, chest pain, dyspnea, abdominal pain, neurologic emergencies, trauma, toxicology and disposition."]},{"heading":"Exam + ward plan","type":"bullets","items":["AMBOSS Emergency Medicine + school protocol teaching.","OnlineMedEd relevant acute-care lessons.","NBME EM CSMS / COMAT-SE where used; simulation for resuscitation. OnlineMedEd | AMBOSS Clerkship Guide | NBME CSMS | COMAT"]},{"heading":"CLINICAL PERFORMANCE","type":"paragraph","text":"For every patient: know the problem representation, differential, key evidence for/against, next diagnostic step, initial management, disposition and what could make the patient worse."}],"page":31},{"name":"YEAR 3 - SHELF / COMAT EXAM SYSTEM","list_label":"YEAR 3 - SHELF / COMAT EXAM SYSTEM","phase":"","category":"Year 3 — Clinical Clerkships","sections":[{"heading":"","type":"table","columns":["Checkpoint","MD / NBME route","DO / COMAT route"],"rows":[["Blueprint","School/NBME subject-exam content + clerkship objectives.","NBOME COMAT discipline blueprint + school objectives."],["Daily questions","UWorld or AMBOSS shelf mode by rotation.","UWorld/AMBOSS + COMLEX-specific bank as needed."],["Mid-rotation","Review question analytics and weak topics; ask for clinical feedback.","Same + ensure OPP/OMM integration."],["1-2 weeks before","NBME Clinical Science Mastery Series form(s).","COMAT-SE + school-provided readiness tools."],["Final days","Targeted weak-topic repair; timed mixed questions; sleep/recovery.","Targeted discipline + OPP review; timed COMAT-style practice."]]},{"heading":"Official assessment resources","type":"bullets","items":["NBME Clinical Science Mastery Series - 50-question self-assessment forms for Medicine, Surgery, Pediatrics, OB/GYN, Psychiatry, Neurology, Family Medicine and Emergency Medicine.","NBOME COMAT Clinical - 120-item, 2.5-hour clinical subject exams with OPP/OMM integration.","AMBOSS Clerkship Guide - useful schedule and study-plan framework.","UWorld Step 2 CK - shelf categories integrated into Step 2 preparation."]}],"page":32},{"name":"YEAR 4 - ADVANCED CLINICAL MEDICINE","list_label":"YEAR 4 - ADVANCED CLINICAL MEDICINE","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"Goal: perform at the edge of intern responsibility while remaining appropriately supervised.","type":"table","columns":["Experience","Expected mastery"],"rows":[["Sub-Internship / Acting Internship","Primary workup, daily management, orders under supervision, notes, handoffs, discharge planning and escalating sick patients."],["Emergency Medicine","Rapid assessment, stabilization, differential, disposition and procedural exposure."],["Critical Care","Shock, ventilatory support, sepsis, hemodynamics, sedation, organ failure and goals-of-care discussions."],["Radiology","Imaging appropriateness, chest/abdominal/neuro basics and communication of urgent findings."],["Anesthesiology / Perioperative Medicine","Airway, analgesia, hemodynamics, perioperative risk and procedural monitoring."],["Specialty Electives","Deepen target-residency knowledge and explore subspecialties."],["Transition to Residency","Intern workflow, cross-cover, handoff, pages, order entry, patient safety, documentation and escalation."],["Residency Application","Specialty selection, letters, personal statement, ERAS, interviews and rank-process education."]]},{"heading":"Goal: perform at the edge of intern responsibility while remaining appropriately supervised. — AAMC RESIDENCY-READINESS LENS","type":"paragraph","text":"Use the AAMC Core EPAs as a practical checklist: gather history/physical, prioritize differential, recommend tests, enter/discuss orders, document, present, hand off, recognize urgent care, obtain consent, contribute to team care and identify system failures."}],"page":33},{"name":"STEP 2 CK + COMLEX LEVEL 2-CE","list_label":"STEP 2 CK + COMLEX LEVEL 2-CE","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"","type":"table","columns":["Exam","Current high-level emphasis","Preparation anchor"],"rows":[["Step 2 CK","Diagnosis, diagnostic studies, management, pharmacotherapy, prevention, prognosis, patient safety and professionalism. Medicine contributes the largest clinical-science share (55-65%).","UWorld Step 2 / AMBOSS + NBME CCSSA + official USMLE practice interface."],["COMLEX Level 2-CE","Clinical care plus foundational science and osteopathic competency domains; musculoskeletal, wellness, neuro/mental health and other clinical presentations remain explicitly weighted.","COMLEX-style Qbank + OPP/OMM + NBOME blueprint/practice resources; optionally combine with Step 2 resources."]]},{"heading":"Longitudinal Step 2 strategy","type":"bullets","items":["Do not postpone Step 2 learning until dedicated: each clerkship is a Step 2 system block.","Finish most shelf-aligned questions during the rotation; review incorrects and build a concise error log.","Use NBME CSMS/COMAT-SE for rotation readiness; use NBME CCSSA for cumulative Step 2 readiness.","During dedicated, switch from specialty silos to mixed timed blocks and management-heavy reasoning.","Practice health maintenance, patient safety, ethics, communication and epidemiology deliberately; these are explicit exam domains."]},{"heading":"Current official links","type":"table","columns":["•","Step 2 CK official page"],"rows":[["•","Step 2 CK content specifications"],["•","NBME CCSSA"],["•","COMLEX-USA Blueprint"],["•","UWorld Step 2 CK"],["•","TrueLearn COMLEX Level 2 / COMAT"]]}],"page":34},{"name":"TRANSITION TO RESIDENCY + STEP 3 / LEVEL 3 PREVIEW","list_label":"TRANSITION TO RESIDENCY + STEP 3 / LEVEL 3 PREVIEW","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"WHY INCLUDE THIS NOW?","type":"paragraph","text":"A strong Year 4 curriculum should not end at the Match. It should close the gap between being a supervised medical student and functioning safely as a new resident."},{"heading":"Residency readiness checklist","type":"bullets","items":["Perform concise pre-rounding, prioritize active problems and anticipate overnight changes.","Give safe handoffs and recognize when a patient is deteriorating.","Write problem-oriented notes and draft orders for supervisor review.","Manage common cross-cover scenarios using local protocols and escalation.","Understand discharge planning, medication reconciliation and follow-up.","Communicate uncertainty, ask for help early and document escalation appropriately."]},{"heading":"Step 3 / COMLEX Level 3","type":"paragraph","text":"Step 3 assesses independent general medical care and includes computer-based case simulations (CCS). COMLEX Level 3 assesses unsupervised osteopathic practice and uses clinical decision-making cases. NBOME has announced a one-day Level 3 format beginning January 13, 2027."},{"heading":"Step 3 / COMLEX Level 3","type":"table","columns":["Exam","Practice emphasis","Official"],"rows":[["USMLE Step 3","Ambulatory and acute management, prevention, biostatistics/epidemiology, prognosis, longitudinal care and CCS cases.","Open"],["COMLEX Level 3","Independent osteopathic management, MCQs + CDM cases, OPP/OMM integration.","Open"]]},{"heading":"BOUNDARY","type":"paragraph","text":"This Academy teaches concepts and exam preparation. Actual patient-care decisions must follow the learner's level of training, supervision, institutional policy and current clinical guidelines."}],"page":35},{"name":"STUDY OPERATING SYSTEM","list_label":"STUDY OPERATING SYSTEM","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"","type":"table","columns":["Cadence","Preclinical years","Clinical years"],"rows":[["Daily","Preview objectives -> learn deeply -> active recall -> 10-25 targeted questions -> brief error review.","Learn from patients -> 10-20 questions in small blocks -> read around patients -> update error list."],["2-3x/week","Spaced repetition of current + prior blocks.","Short spaced review of rotation-specific facts and prior errors."],["Weekly","One mixed cumulative question block under time.","One larger timed shelf/Step 2 block + one clinical skill/reflection goal."],["End of block/rotation","Timed mixed questions + school exam/practical + remediation.","NBME/COMAT-style self-assessment + clinical feedback + targeted final review."],["Monthly","Review analytics: weakest systems, error type and retention.","Review cumulative Step 2/Level 2 performance and revisit prior clerkships."]]},{"heading":"Error log taxonomy","type":"bullets","items":["Knowledge gap: never learned or forgot the fact/mechanism.","Reasoning gap: knew facts but misinterpreted the vignette.","Question-reading gap: missed the task/lead-in or ignored a key detail.","Management-sequence gap: chose a reasonable action but not the best next step.","Overthinking: changed from the most likely/common answer without adequate evidence.","Time-pressure gap: slow interpretation or calculations."]}],"page":36},{"name":"READINESS GATES - DO NOT USE A SINGLE SCORE","list_label":"READINESS GATES - DO NOT USE A SINGLE SCORE","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"","type":"table","columns":["Gate","Evidence to look for"],"rows":[["Content coverage","All blueprint domains have been learned at least once and tested with questions."],["Question-bank learning","Performance trend improving; explanations reviewed; old errors retested."],["External assessments","Multiple recent official or high-quality external assessments are concordant rather than one isolated result."],["Timed endurance","Can complete blocks at target pace without a major late-block collapse."],["Error stability","High-frequency weak areas are shrinking; repeated identical mistakes are uncommon."],["Wellness/logistics","Sleep, breaks, exam software familiarity, testing logistics and accommodations are ready."],["School approval","Follow school-specific requirements for authorization, timing and graduation/promotion."]]},{"heading":"NO PASS GUARANTEE","type":"paragraph","text":"A curriculum can maximize coverage and preparation, but no resource stack can guarantee a school or licensing-exam result. Readiness decisions should use official assessments, school guidance and the learner's full performance pattern."}],"page":37},{"name":"PRIMARY BENCHMARK & OFFICIAL SOURCES","list_label":"PRIMARY BENCHMARK & OFFICIAL SOURCES","phase":"","category":"Year 4 — Advanced Clinical & Transition","sections":[{"heading":"","type":"bullets","items":["University of Washington School of Medicine curriculum","Stanford Medicine MD curriculum / 2026-27 requirements","Harvard Medical School Pathways","Johns Hopkins Genes to Society curriculum","PNWU-COM osteopathic curriculum","USMLE Step 1 official content & format","USMLE Step 2 CK official content & format","USMLE Step 3 official content","NBOME COMLEX-USA Blueprint","NBOME COMLEX-USA examination format","NBOME COMAT Clinical Subject Exams","NBME Self-Assessments","AAMC Core Entrustable Professional Activities"]},{"heading":"CURATED LEARNING RESOURCES","type":"bullets","items":["UWorld Medical","AMBOSS","Pathoma","OnlineMedEd","Stanford Medicine 25","TrueLearn COMLEX","Ninja Nerd Pharmacodynamics","Ninja Nerd Microbiology Foundations","Ninja Nerd Immunology/Inflammation","Ninja Nerd Embryology/Gastrulation"]},{"heading":"NEXT EXPANSION — Build the Academy course-by-course. Recommended next module: Medical School Year 1 - Anatomy, Histology & Embryology, expanded into a complete semester-level learning path with topic sequence, long-form videos, anatomy practical","type":"paragraph","text":"strategy, question practice and school/Step/COMLEX crosswalk."}],"page":38},{"name":"REVIEW EXPANSION - V2","list_label":"REVIEW EXPANSION - V2","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"This expansion adds a second learning layer: structured content review for school exams plus dedicated USMLE, COMLEX, Shelf/NBME and COMAT review tracks. The goal is not resource accumulation; it is repeated retrieval, application, assessment and targeted remediation. What changes in v2","type":"bullets","items":["Every major phase now has a review layer: block review -> cumulative review -> professional-exam review.","Review is blueprint-driven: official USMLE/NBOME/NBME specifications determine what must remain retrievable.","Video review is role-specific: deep concept videos for weak mechanisms, concise board review for consolidation, clinical videos for reasoning and bedside skills.","Question banks remain central: content review is followed immediately by vignette practice; explanations become the remediation map.","Readiness uses multiple signals: school performance, question-bank trends, official self-assessments, timing/endurance and error stability."]},{"heading":"Jump to review tracks — School content review","type":"paragraph","text":"Year 1 review | Year 2 review | Clerkship review"},{"heading":"Jump to review tracks — Professional exams","type":"paragraph","text":"USMLE Step 1 | COMLEX Level 1 | Step 2 CK | Level 2-CE | Step 3 / Level 3"},{"heading":"Resource system","type":"paragraph","text":"Resource decision matrix | Official + curated sources"},{"heading":"Master rule — Use one primary content source, one primary question bank, official assessments, and targeted supplemental videos only when the data show a weakness. A learner should be able to explain the mechanism, recognize the pattern, choose the next diagnostic/management step, and defend why competing answers are wrong.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":39},{"name":"THE THREE-LAYER REVIEW SYSTEM","list_label":"THE THREE-LAYER REVIEW SYSTEM","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["Layer","Purpose","What “done” looks like"],"rows":[["1. Block / course review","Pass the school exam without losing mechanistic understanding.","Objectives mapped; closed-book recall; practical/image review; targeted questions; one timed mixed set."],["2. Cumulative spiral review","Prevent forgetting as later blocks accumulate.","Prior systems revisited weekly; spaced errors retested; mixed questions include old material."],["3. Professional-exam review","Reorganize school knowledge around the national exam blueprint and vignette style.","Blueprint coverage complete; mixed timed blocks; official self-assessments concordant; weak domains repaired and retested."]]},{"heading":"Content review recipe: 60-120 minutes per weak topic","type":"bullets","items":["Retrieve first: write/draw the pathway, anatomy, differential or management algorithm from memory before opening notes.","Repair the mechanism: use a substantive video or core text only for what you cannot explain.","Compress: create a one-page mechanism map, comparison table or illness script.","Apply: complete 10-25 targeted questions immediately; review every distractor.","Retest later: repeat missed concepts after 48-72 hours and again in a mixed block the following week."]},{"heading":"Content review recipe: 60-120 minutes per weak topic — How school exams and boards differ","type":"table","columns":["School assessment","Professional board assessment"],"rows":[["May emphasize local lectures, faculty phrasing, detailed practical identification and course-specific objectives.","Emphasizes transferable mechanism, pattern recognition, integration across disciplines and standardized clinical reasoning."],["Review every stated school objective and locally emphasized image/lab/practical.","Overlay the official blueprint and practice in mixed vignette format."],["Goal: demonstrate mastery of the current block. 2026/27 review-expanded edition - verify official exam updates before testing","Goal: retain and integrate the entire curriculum under time pressure."]]}],"page":40},{"name":"YEAR 1 CONTENT REVIEW - FOUNDATIONAL SCIENCES I","list_label":"YEAR 1 CONTENT REVIEW - FOUNDATIONAL SCIENCES I","phase":"These pages convert the Year 1 curriculum into explicit review targets. Review depth should follow the school objectives first,","category":"Review System — Year 1 & 2","sections":[{"heading":"then the Step 1/Level 1 blueprint.","type":"table","columns":["Domain","Must retrieve without notes","Review bridge","Question / assessment"],"rows":[["Anatomy + Embryology","Regional relationships; neurovascular supply; dermatomes; spaces; cross-sections; germ layers; folding; organ development; congenital anomalies.","Bootcamp anatomy; Ninja Nerd; cadaver/radiology practicals","School practicals + UWorld/AMBOSS anatomy/embryology questions."],["Histology + Cell Biology","Tissue identification; organ microanatomy; membranes; organelles; cell cycle; signaling; cytoskeleton; apoptosis.","AMBOSS; Boards & Beyond","Image-rich school questions + board-style cell biology/histology."],["Genetics + Molecular Biology","Inheritance patterns; penetrance; trinucleotide repeats; imprinting; DNA replication/repair; transcription/translation; gene regulation; molecular diagnostics.","Boards & Beyond; Bootcamp","Pedigree/calculation questions + molecular disease vignettes."],["Biochemistry + Metabolism","Enzyme kinetics; vitamins/cofactors; fed/fasted states; glycolysis/TCA/ETC; glycogen; FA/ketone; AA/urea; inborn errors.","Boards & Beyond; Bootcamp; Ninja Nerd","Draw pathways from memory -> targeted Qbank -> mixed metabolic cases."]]},{"heading":"Review test","type":"bullets","items":["Can you draw the pathway/anatomy without prompts?","Can you predict the clinical consequence when one step is disrupted?","Can you interpret the relevant image, pedigree, lab pattern or radiograph?","Can you connect the mechanism to a clinical vignette and eliminate distractors? 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":41},{"name":"YEAR 1 CONTENT REVIEW - FOUNDATIONAL SCIENCES II","list_label":"YEAR 1 CONTENT REVIEW - FOUNDATIONAL SCIENCES II","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["Domain","Must retrieve without notes","Review bridge","Question / assessment"],"rows":[["Physiology","Membrane potentials; autonomics; pressure/flow; cardiac cycle; gas exchange; acid-base; GFR/tubular handling; endocrine feedback; GI motility; reproductive physiology.","Ninja Nerd; Cardiology physiology","Graph interpretation + mechanism-heavy Qbank."],["Immunology","Innate/adaptive cells; antigen presentation; cytokines; antibodies; complement; hypersensitivity; autoimmunity; immunodeficiency; transplant; immunotherapies.","Ninja Nerd; Sketchy","Mechanism maps + immunodeficiency/hypersensitivity vignettes."],["Microbiology","Organism classification; virulence; toxins; transmission; syndromes; diagnostics; resistance; antimicrobials.","Sketchy Micro; Ninja Nerd","Organism-from-clue retrieval + antimicrobial questions."],["Pharmacology foundations","PK/PD; receptor curves; agonists/antagonists; clearance/Vd; CYP; autonomics; adverse reactions; interactions.","Boards & Beyond; Ninja Nerd cardiovascular pharm","Dose-response calculations + adverse-effect/interaction vignettes."]]},{"heading":"Free long-form review examples","type":"bullets","items":["Ninja Nerd Cardiology physiology topic library - linked lectures include cardiac electrophysiology, cardiac cycle, output and blood-pressure regulation.","Ninja Nerd Cardiovascular Pharmacology - multi-hour lectures on antihypertensives, antiarrhythmics, anticoagulants, heart failure and lipids. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":42},{"name":"YEAR 1 CONTENT REVIEW - DISEASE + CLINICAL FOUNDATIONS","list_label":"YEAR 1 CONTENT REVIEW - DISEASE + CLINICAL FOUNDATIONS","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["Domain","Must retrieve without notes","Review bridge","Question / assessment"],"rows":[["General pathology","Cell injury/death; inflammation; healing; hemodynamics; thrombosis; shock; neoplasia; tumor biology.","Pathoma; Boards & Beyond","Pathoma-style mechanism review -> UWorld/AMBOSS pathology."],["Neuroscience + behavior","Neuroanatomy/localization; tracts; cranial nerves; neurotransmitters; sleep; learning; development; defense mechanisms; psychiatric foundations.","Bootcamp; Ninja Nerd","Localization + lesion vignettes; behavioral scenarios."],["Biostats / Epi / EBM","Study designs; bias/confounding; sensitivity/specificity; predictive values; likelihood ratios; ARR/RRR/NNT; confidence intervals; trial interpretation.","AMBOSS; official question practice","Timed calculations + abstract/table interpretation."],["Clinical skills I","H&P; problem representation; oral presentation; note structure; evidence-based physical exam; communication.","Strong Medicine physical exam course; Stanford Medicine 25","OSCE/standardized patient + feedback; write one note/presentation per case."],["OPP/OMM - DO","Osteopathic principles; structural exam; somatic dysfunction; viscerosomatics; Chapman points; counterstrain; muscle energy; HVLA principles/contraindications.","Boards & Beyond OMM; school OMM lab","Hands-on lab + COMLEX-style OMM/OPP questions."]]},{"heading":"Practical review bridge","type":"paragraph","text":"Strong Medicine - evidence-based physical exam course introduction and Stanford Medicine 25 video gallery should supplement, not replace, supervised skills lab and standardized-patient practice. 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":43},{"name":"YEAR 1 SCHOOL-EXAM REVIEW CYCLE - 7 DAYS","list_label":"YEAR 1 SCHOOL-EXAM REVIEW CYCLE - 7 DAYS","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["When","Primary task","Output"],"rows":[["D-7 to D-6","Map every school objective to a review checklist. Identify practical/image content separately.","One objective tracker; red/yellow/green confidence rating."],["D-5","Closed-book mechanism review: redraw pathways/anatomy; teach aloud; 30-50 targeted questions.","Weak-mechanism list; first error log."],["D-4","High-yield content repair using one video source; re-do missed questions.","Compressed one-page summaries / illness scripts."],["D-3","Mixed school-style + board-style questions; histology/radiology/cadaver images where applicable.","Timed performance trend + image/practical misses."],["D-2","Full cumulative review: prior blocks + current block; practical stations; calculations.","No unresolved high-frequency objectives."],["D-1","Short retrieval only; no new resource binge. Logistics, sleep and confidence calibration.","Final 1-2 page rapid-review sheet."],["Exam day","Read lead-in first when helpful; identify task; commit to best answer; move on.","Post-exam: classify errors only after recovery."]]},{"heading":"Block review minimums","type":"bullets","items":["At least one timed mixed set before the exam.","At least one closed-book “blank page” review of the major mechanisms.","For anatomy/histology: timed image/practical retrieval, not only text questions.","For OMM: hands-on competence plus question-based recognition of indications/contraindications.","Retest high-frequency misses after 48-72 hours. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":44},{"name":"YEAR 1 CUMULATIVE REVIEW - END-OF-TERM","list_label":"YEAR 1 CUMULATIVE REVIEW - END-OF-TERM","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"Four-pass cumulative review","type":"table","columns":["Pass","What to do"],"rows":[["1. Coverage audit","Verify every Year 1 domain has been learned and questioned at least once."],["2. Mechanism reconstruction","Redraw biochem, physiology, immune and path mechanisms from memory; map anatomy and neuroanatomy."],["3. Mixed cases","Use mixed questions so the diagnosis is not cued by the chapter title."],["4. Readiness check","Use school cumulative exam or a high-quality external basic-science assessment when appropriate; remediate by error type."]]},{"heading":"Integrated case prompts","type":"bullets","items":["Anemia: connect hematopoiesis -> iron/B12/folate biochemistry -> RBC morphology -> physiology -> pathology.","Sepsis: connect microbiology -> innate immunity -> cytokines -> vascular physiology -> shock -> antimicrobial pharmacology.","Diabetes: connect insulin signaling -> carbohydrate/lipid metabolism -> endocrine physiology -> micro/macrovascular pathology -> drug mechanisms.","Neurologic lesion: localize anatomy -> explain physiology -> predict exam findings -> choose diagnostic test."]},{"heading":"These integrations become the scaffold for Year 2 organ-system learning and later Step 1/COMLEX review.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":45},{"name":"YEAR 2 SYSTEMS REVIEW - CARDIOVASCULAR, RESPIRATORY, RENAL","list_label":"YEAR 2 SYSTEMS REVIEW - CARDIOVASCULAR, RESPIRATORY, RENAL","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["System","Review spine","High-value review resources","Questions must test"],"rows":[["Cardiovascular","Hemodynamics -> electrophysiology -> ischemia/heart failure/valves -> pathology -> ECG/imaging -> drugs.","Ninja Nerd cardiology; Pathoma; Strong Medicine ECG","Murmurs, pressure-volume, ECG, shock, pharmacology, next diagnostic/therapeutic step."],["Respiratory","V/Q and gas exchange -> PFTs -> obstructive/restrictive -> infections -> vascular disease -> neoplasm -> drugs/ventilation basics.","Ninja Nerd; Pathoma","ABG/PFT, imaging, pathology, hypoxemia mechanism, management."],["Renal","GFR/tubular transport -> electrolytes -> acid-base -> AKI/CKD -> nephritic/nephrotic -> HTN -> diuretics.","Ninja Nerd; Boards & Beyond","Acid-base, electrolyte patterns, urine findings, renal pathology, diuretics and BP drugs."]]},{"heading":"Review algorithm for each system","type":"bullets","items":["Normal physiology first.","Name the pathophysiologic failure.","Predict signs, labs, imaging and pathology.","Choose the confirmatory/next test.","Choose the mechanism-based treatment and know major adverse effects.","Finish with mixed timed questions and an error-driven re-review. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":46},{"name":"YEAR 2 SYSTEMS REVIEW - GI, ENDOCRINE, REPRODUCTIVE","list_label":"YEAR 2 SYSTEMS REVIEW - GI, ENDOCRINE, REPRODUCTIVE","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["System","Review spine","High-value review resources","Questions must test"],"rows":[["GI / hepatobiliary / nutrition","Motility/secretions -> malabsorption -> inflammatory disease -> liver/biliary -> pancreas -> GI tumors -> nutrition.","Boards & Beyond; Pathoma","Lab patterns, diarrhea/malabsorption, liver injury patterns, imaging/endoscopy choices, nutrition deficiencies."],["Endocrine","Hypothalamic-pituitary axes -> thyroid/adrenal -> diabetes -> calcium/bone -> endocrine tumors -> pharmacology.","Ninja Nerd; Bootcamp","Feedback loops, stimulation/suppression testing, electrolyte patterns, diabetes treatment."],["Reproductive 2026/27 review-expanded edition - verify official exam updates before testing","Embryology/anatomy -> menstrual physiology -> infertility -> pregnancy physiology -> reproductive pathology -> contraception/fertility drugs.","Boards & Beyond; Sketchy","Hormone patterns, congenital anomalies, reproductive cancers, pregnancy complications, pharmacology."]]}],"page":47},{"name":"YEAR 2 SYSTEMS REVIEW - HEME/ONC + INFECTIOUS DISEASE","list_label":"YEAR 2 SYSTEMS REVIEW - HEME/ONC + INFECTIOUS DISEASE","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["System","Review spine","High-value review resources","Questions must test"],"rows":[["Hematology","RBC production -> anemias/hemolysis -> WBC disorders -> coagulation -> thrombosis -> transfusion.","Pathoma; Boards & Beyond","CBC/smear interpretation, coagulation labs, transfusion reactions, anticoagulants."],["Oncology","Cell cycle/tumor suppressors -> carcinogenesis -> tumor patterns -> staging/prognosis concepts -> chemo/immunotherapy toxicities.","Pathoma; Sketchy","Paraneoplastic syndromes, tumor markers, pathology, treatment toxicities."],["Infectious disease","Syndrome -> likely pathogen -> specimen/test -> empiric therapy -> definitive therapy -> resistance/prevention.","Sketchy Micro/Pharm; Ninja Nerd","Organism clues, antimicrobial spectrum/adverse effects, immune status, infection control."]]},{"heading":"Antimicrobial review rule","type":"bullets","items":["Learn by syndrome as well as by organism.","For every drug: mechanism, spectrum, major toxicity, resistance mechanism and the clinical situation where it is preferred.","When a question bank miss reveals a forgotten organism/drug association, use visual mnemonic review selectively rather than rewatching the whole library. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":48},{"name":"YEAR 2 SYSTEMS REVIEW - MSK/DERM/RHEUM + NEURO/PSYCH","list_label":"YEAR 2 SYSTEMS REVIEW - MSK/DERM/RHEUM + NEURO/PSYCH","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["System","Review spine","High-value review resources","Questions must test"],"rows":[["MSK / rheumatology","Anatomy -> bone/joint pathology -> inflammatory vs degenerative -> autoantibodies -> crystal disease -> drugs.","Boards & Beyond; Pathoma","Pattern recognition, antibody interpretation, imaging, immunosuppressants/NSAIDs."],["Dermatology","Morphology -> distribution -> inflammatory/infectious -> blistering -> drug eruptions -> skin cancer.","AMBOSS; Sketchy","Image recognition, lesion description, biopsy/management."],["Neurology","Localization -> vascular -> seizure -> headache -> movement -> demyelination -> neuromuscular -> neurodegeneration.","Bootcamp; Ninja Nerd","Localization, CT/MRI patterns, neuropharm, emergency management."],["Psychiatry 2026/27 review-expanded edition - verify official exam updates before testing","MSE -> mood/psychosis/anxiety/trauma -> substance -> personality -> child -> sleep -> psychopharm.","OnlineMedEd; Sketchy","Diagnostic criteria distinctions, adverse effects, emergency safety, therapy indications."]]}],"page":49},{"name":"YEAR 2 INTEGRATED REVIEW - THE 7-LINK CHAIN","list_label":"YEAR 2 INTEGRATED REVIEW - THE 7-LINK CHAIN","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["Link","Question to answer"],"rows":[["","What is normal anatomy/physiology/histology?"],["","What mechanism has broken?"],["","What symptoms/signs/labs/images follow from that failure?"],["","What close mimics must be separated?"],["","What is the best next diagnostic step or confirmatory test?"],["","What is first-line/definitive treatment and why?"],["","What can worsen, recur, become toxic, or require escalation?"]]},{"heading":"One disease, three exam lenses","type":"bullets","items":["School exam: include locally emphasized mechanisms, lecture images and details.","Step 1: mechanism, pathology, physiology and pharmacology embedded in a clinical vignette.","COMLEX Level 1: the same clinical science plus OPP/OMM, osteopathic competency and musculoskeletal emphasis."]},{"heading":"One disease, three exam lenses — Do not create separate factual universes for school and boards. Create one integrated disease model, then practice it in the assessment style you will face.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":50},{"name":"FROM YEAR 2 TO DEDICATED: PRE-BOARD TRANSITION","list_label":"FROM YEAR 2 TO DEDICATED: PRE-BOARD TRANSITION","phase":"","category":"Review System — Year 1 & 2","sections":[{"heading":"","type":"table","columns":["Checkpoint","Action"],"rows":[["8-12 weeks before dedicated","Finish first-pass core content; begin mixed cumulative questions; identify weakest systems by data rather than feeling."],["4-8 weeks before dedicated","Increase mixed blocks; complete first official/self-assessment baseline if school policy permits; create repair list by system + error type."],["Start of dedicated","Stop following the school sequence. Follow the national blueprint and your weakest domains."],["During dedicated","Questions drive the day; content review repairs misses. Use official assessments at planned intervals."],["Final week","Revisit recurring errors, high-frequency formulas/tables, ethics/patient safety, image patterns, and exam interface. Avoid adding new broad resources."]]},{"heading":"Resource hierarchy","type":"bullets","items":["Primary concept system: choose Boards & Beyond or Bootcamp as the main structured review if needed.","Pathology: Pathoma for mechanistic pathology consolidation.","Microbiology/pharmacology memory: Sketchy selectively when visual encoding improves recall.","Deep mechanism repair: Ninja Nerd for difficult physiology/pharmacology topics.","Questions: UWorld Step 1 as primary; AMBOSS Step 1 for additional targeted practice/library integration.","Readiness: official NBME self-assessments and USMLE sample experience. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":51},{"name":"USMLE STEP 1 - BLUEPRINT-DRIVEN REVIEW","list_label":"USMLE STEP 1 - BLUEPRINT-DRIVEN REVIEW","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"Step 1 is pass/fail, but the preparation standard should be broad conceptual mastery. Official USMLE guidance emphasizes application of foundational science, not memorization of isolated facts.","type":"table","columns":["Official content emphasis","Current range"],"rows":[["Pathology","45-55% discipline overlap"],["Physiology","30-40%"],["Nutrition","15-20%"],["Gross anatomy & embryology","10-20%"],["Microbiology","10-20%"],["Pharmacology","10-20%"],["Behavioral sciences","10-15%"],["Biochemistry","5-15%"],["Histology & cell biology","5-15%"],["Immunology","5-15%"],["Genetics","5-10%"]]},{"heading":"System emphasis","type":"paragraph","text":"The official 2026 outline distributes foundational science across organ systems. High-weight combined groupings include reproductive/endocrine (12-16%), respiratory + renal/urinary (11-15%), behavioral health + nervous/special senses (10-14%), and blood/lymphoreticular/immune (9-13%). Open official Step 1 specifications"},{"heading":"What this means for review","type":"bullets","items":["Pathology and physiology must be continuously integrated with every system.","Do not leave nutrition, communication/social science, biostatistics or patient-safety concepts for the last day.","Practice interpreting graphs, tables, pathology/histology images and mechanistic experiments, not just text stems. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":52},{"name":"USMLE STEP 1 - CONTENT REVIEW STACK","list_label":"USMLE STEP 1 - CONTENT REVIEW STACK","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"","type":"table","columns":["Need","Recommended resource role","Do not misuse it"],"rows":[["Structured full review","Boards & Beyond or Bootcamp","Do not watch every minute if practice data show strong mastery."],["Pathology consolidation","Pathoma","Pair with questions; do not treat memorized chapter lines as clinical reasoning."],["Micro / pharm durable recall","Sketchy","Use where visual encoding helps; confirm understanding of mechanism and clinical use."],["Deep mechanism repair","Ninja Nerd","Use selectively for hard physiology, pharmacology or disease mechanisms."],["Primary Qbank","UWorld Step 1","Review explanations deeply; random percentages alone are not a mastery plan."],["Integrated reference + extra questions","AMBOSS Step 1","Use targeted sessions and library links to repair misses."],["Official readiness","NBME self-assessments + official USMLE sample/interface","Do not make a go/no-go decision from one isolated score."]]},{"heading":"First Aid role — Use First Aid as a compressed index/checklist and annotation anchor. It is most effective when paired with understanding + questions, not as a standalone textbook.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":53},{"name":"USMLE STEP 1 - 6-WEEK DEDICATED TEMPLATE","list_label":"USMLE STEP 1 - 6-WEEK DEDICATED TEMPLATE","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"","type":"table","columns":["Week","Core emphasis","Assessment / output"],"rows":[["1","Baseline + weak-system repair. Mixed 40-question blocks; review pathology/physiology gaps.","Baseline NBME/self-assessment if appropriate; error taxonomy established."],["2","Cardio/resp/renal + hematology/immune; continue mixed questions daily.","Retest Week 1 misses; image/pathology review."],["3","GI/endocrine/repro + nutrition; biochem/genetics reinforcement.","Timed mixed blocks; one cumulative review day."],["4","Neuro/psych + MSK/derm + micro/pharm; communication/ethics/biostats integrated.","Second official assessment; compare domain trends, not just total score."],["5","Weakest domains only; increase random timed work; revisit recurrent errors.","Third assessment when schedule/need supports it; endurance simulation."],["6","Consolidation: recurring errors, high-frequency images, equations, ethics/patient safety, official practice interface.","Final readiness evidence should be concordant across multiple recent data points."]]},{"heading":"Daily core","type":"bullets","items":["1-2 timed mixed Qbank blocks depending on stage/endurance.","Deep review of explanations with a short error log.","60-120 minutes of targeted content repair from misses.","Spaced retrieval of prior errors, formulas, images and mechanisms.","Sleep/exercise/break plan that matches the 8-hour testing demand. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":54},{"name":"USMLE STEP 1 - READINESS + REMEDIATION","list_label":"USMLE STEP 1 - READINESS + REMEDIATION","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"Official assessment role","type":"paragraph","text":"NBME Comprehensive Basic Science Self-Assessments are designed to evaluate Step 1-style basic-science readiness; the updated NBME interface now more closely resembles the USMLE experience. NBME self-assessments"},{"heading":"Official assessment role","type":"table","columns":["Pattern","Response"],"rows":[["Low total + broad weakness","Return to structured content review by system; reduce random-question volume temporarily while rebuilding mechanisms."],["Adequate total + one weak system","Target that system with focused content + 40-80 questions, then retest in mixed blocks."],["Knowledge strong but timing poor","Timed half-blocks/blocks; practice lead-in identification; reduce post-answer rumination."],["Repeated management/ethics misses","Build explicit frameworks; practice scenario questions; review why each distractor violates sequence/principle."],["High variance across assessments","Do not schedule from the best result alone; seek a stable upward trend and school guidance."]]},{"heading":"Step 1 exam interface","type":"paragraph","text":"For exams on/after May 14, 2026, Step 1 uses fourteen 30-minute blocks in an 8-hour session, with no more than 20 questions per block. Practice the current official interface before test day. Official Step 1 content/format 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":55},{"name":"COMLEX-USA LEVEL 1 - BLUEPRINT REVIEW","list_label":"COMLEX-USA LEVEL 1 - BLUEPRINT REVIEW","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"The DO review track should not be “Step 1 plus a weekend of OMM.” OPP/OMM and osteopathic competency are explicit blueprint domains throughout preparation.","type":"table","columns":["Dimension 1 competency domain","Minimum %"],"rows":[["Osteopathic Principles, Practice & Manipulative Treatment","12%"],["Osteopathic Patient Care & Procedural Skills","6%"],["Application of Knowledge for Osteopathic Medical Practice","60%"],["Practice-Based Learning & Improvement","4%"],["Interpersonal & Communication Skills","3%"],["Professionalism","3%"],["Systems-Based Practice","2%"]]},{"heading":"Clinical presentation emphasis","type":"paragraph","text":"Current Level 1 minimums include musculoskeletal 13%; wellness/community health 12%; nervous/mental health 10%; GI/nutrition 10%; circulatory/hematologic 10%; respiratory 10%; and smaller explicit domains for development/reproduction, endocrine, renal/breast and integumentary. Official Level 1 page | COMLEX blueprint 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":56},{"name":"COMLEX LEVEL 1 - RESOURCE + OMM INTEGRATION","list_label":"COMLEX LEVEL 1 - RESOURCE + OMM INTEGRATION","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"","type":"table","columns":["Purpose","Primary option","How to use"],"rows":[["Biomedical content","Same structured Step 1 core: Boards & Beyond / Bootcamp + Pathoma","Build mechanisms once; do not duplicate the entire curriculum."],["COMLEX-style questions","TrueLearn COMLEX or another school-approved COMLEX bank","Run longitudinally; tag OMM/OPP and communication/professionalism misses separately."],["OMM / OPP","School OMM lab + OMM review series such as Boards & Beyond OMM","Hands-on techniques, indications/contraindications, viscerosomatics, Chapman points and structural diagnosis."],["Official readiness","COMSAE + NBOME practice resources","Use school policy for required COMSAEs/cutoffs; review domain profile."]]},{"heading":"OMM weekly spiral","type":"bullets","items":["15-30 minutes 3x/week during preclinical blocks instead of cramming at the end.","One hands-on lab retrieval session weekly when feasible.","Integrate OMM into clinical presentations: headache, back pain, rib dysfunction, respiratory complaints, pregnancy, GI complaints, autonomic/viscerosomatic relationships.","Track technique contraindications and safety as carefully as memorized setup positions. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":57},{"name":"COMLEX LEVEL 1 - DEDICATED + READINESS","list_label":"COMLEX LEVEL 1 - DEDICATED + READINESS","phase":"","category":"Review System — Step 1 / Level 1","sections":[{"heading":"","type":"table","columns":["Week structure","COMLEX-specific addition to Step 1-style study"],"rows":[["Daily","Mixed biomedical questions + dedicated COMLEX/OMM set; review osteopathic competency misses."],["2-3x/week","OMM content retrieval + practical setup review; communication/professionalism/system-based practice scenarios."],["Weekly","One timed COMLEX-style set emphasizing longer clinical context and osteopathic integration."],["Periodic","COMSAE or school-required readiness assessment; compare blueprint-domain profile across attempts."],["Final week","OMM rapid sheet, viscerosomatics, Chapman points, autonomics, technique contraindications, ethics/communication and exam interface."]]},{"heading":"2026 format","type":"paragraph","text":"NBOME reduced Level 1 to 320 questions in 2026; current official pages should be checked for session/break details before testing. Level 1 official page | COMLEX examination/blueprint resources 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":58},{"name":"CLERKSHIP CONTENT REVIEW SYSTEM","list_label":"CLERKSHIP CONTENT REVIEW SYSTEM","phase":"Year 3 review must serve two masters: real patient care and end-of-rotation exams. The patient is the anchor; the Qbank and","category":"Review System — Clerkships & Shelf Exams","sections":[{"heading":"official subject blueprint ensure complete coverage.","type":"table","columns":["Daily","Twice weekly","Mid-rotation","Final 7-10 days"],"rows":[["Read around 1-3 patients; 10-20 rotation questions; update illness scripts and error","One larger timed block; review a presentation you did not see clinically;","Use Qbank analytics + attending feedback; target weak chief complaints and","NBME CSMS or COMAT-SE; timed mixed questions; high-yield algorithms;"],["log.","practice oral presentation/notes.","management sequences.","sleep/endurance."]]},{"heading":"Clinical illness-script template","type":"bullets","items":["Who gets it? - age, risk factors, setting.","How does it present? - chief complaint, key symptoms/signs.","What dangerous alternatives must be excluded first?","What is the best next test? What test confirms?","What is initial management? Definitive management? Disposition?","What complications, adverse effects or follow-up change the plan? NBME Clinical Science Mastery Series currently covers Medicine, Surgery, Pediatrics, OB/GYN, Psychiatry, Neurology, Family Medicine and Emergency Medicine, with 50 questions per form. NBME CSMS COMAT Clinical covers major DO clerkship disciplines in 120-item, 2.5-hour exams with OPP/OMM integration. COMAT official 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":59},{"name":"SHELF / COMAT REVIEW - INTERNAL MEDICINE","list_label":"SHELF / COMAT REVIEW - INTERNAL MEDICINE","phase":"","category":"Review System — Clerkships & Shelf Exams","sections":[{"heading":"Content review spine","type":"bullets","items":["Cardiology, pulmonology, GI/hepatology, renal/electrolytes, endocrine, hematology/oncology, infectious disease, rheumatology, neurology overlap and preventive care.","Prioritize diagnostic sequence, inpatient vs outpatient management, medication selection, contraindications, complications and disposition.","Know common algorithms: chest pain/ACS, dyspnea, sepsis, AKI/electrolytes, GI bleed, cirrhosis, diabetes emergencies, anemia, fever/immunocompromise."]},{"heading":"Resource stack","type":"table","columns":["Content","Questions","Readiness"],"rows":[["OnlineMedEd IM or Boards & Beyond clinical","UWorld Step 2 / AMBOSS","NBME CSMS; DO: COMAT + COMLEX-specific bank"]]},{"heading":"Ward-to-exam bridge — For every admitted patient, create a one-line problem representation, 3-item differential, key test, initial treatment, disposition and one “what would make this patient worse?” question. This converts patient exposure into shelf/Step 2 reasoning.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":60},{"name":"SHELF / COMAT REVIEW - SURGERY + EMERGENCY MEDICINE","list_label":"SHELF / COMAT REVIEW - SURGERY + EMERGENCY MEDICINE","phase":"","category":"Review System — Clerkships & Shelf Exams","sections":[{"heading":"Surgery","type":"bullets","items":["Pre-op risk and fluids/electrolytes; acute abdomen; trauma; GI surgery; breast; vascular; endocrine surgery; postoperative fever/complications.","Use “unstable first” reasoning: ABCs/resuscitation before definitive diagnosis when appropriate.","Learn when to observe, image, operate, drain, give antibiotics, anticoagulate or escalate."]},{"heading":"Emergency Medicine","type":"bullets","items":["ABCs, shock, chest pain, dyspnea, abdominal pain, altered mental status, stroke, seizures, trauma, toxicology, environmental emergencies and disposition.","Simulation/clinical protocols matter for real care; exam review must still follow standardized next-step reasoning."]},{"heading":"Resources","type":"paragraph","text":"OnlineMedEd clinical | UWorld Step 2 | AMBOSS | NBME CSMS | COMAT 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":61},{"name":"SHELF / COMAT REVIEW - PEDIATRICS + OB/GYN","list_label":"SHELF / COMAT REVIEW - PEDIATRICS + OB/GYN","phase":"","category":"Review System — Clerkships & Shelf Exams","sections":[{"heading":"Pediatrics review spine","type":"bullets","items":["Growth/development and milestones; newborn care; vaccines/prevention; respiratory/GI/infectious disease; congenital disease; pediatric emergencies.","Always adjust differential, vitals, labs, fluids and medication reasoning for age/weight.","Revisit developmental milestones and immunization/prevention repeatedly because they are easy to forget between systems."]},{"heading":"OB/GYN review spine","type":"bullets","items":["Prenatal care, fetal testing, labor management, postpartum; hypertensive disease; bleeding; ectopic/miscarriage; contraception; infertility; abnormal uterine bleeding; gynecologic oncology.","Build explicit management algorithms for trimester-specific bleeding, labor progression, fetal heart tracing, preeclampsia and postpartum emergencies."]},{"heading":"Resources","type":"paragraph","text":"OnlineMedEd clinical | UWorld Step 2 | AMBOSS | NBME CSMS | COMAT 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":62},{"name":"SHELF / COMAT REVIEW - PSYCHIATRY + NEUROLOGY + FAMILY MEDICINE","list_label":"SHELF / COMAT REVIEW - PSYCHIATRY + NEUROLOGY + FAMILY MEDICINE","phase":"","category":"Review System — Clerkships & Shelf Exams","sections":[{"heading":"Psychiatry","type":"bullets","items":["MSE, suicide/violence risk, mood, psychosis, anxiety/trauma, substance use, personality, child psychiatry, sleep, medication adverse effects.","Differentiate look-alike diagnoses by duration, functional impairment and exclusion criteria; know emergency safety and medication toxicity."]},{"heading":"Neurology","type":"bullets","items":["Localization before disease label; stroke, seizure, headache, movement, demyelination, neuromuscular, peripheral nerve and neuro emergencies.","Strong Medicine ECG is not neuro; use bedside neuro exam via Stanford Medicine 25 and supervised examination."]},{"heading":"Family Medicine","type":"bullets","items":["Preventive care, screening, vaccination, chronic disease, common ambulatory complaints, dermatology/MSK, women’s health, pediatrics and behavioral health.","Preventive recommendations and outpatient follow-up/disposition are high-yield because they differ from inpatient reflexes. NBME CSMS | COMAT clinical subjects | UWorld Step 2 | AMBOSS 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":63},{"name":"USMLE STEP 2 CK - BLUEPRINT REVIEW","list_label":"USMLE STEP 2 CK - BLUEPRINT REVIEW","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"Step 2 CK is predominantly a patient-care decision exam. Content review must therefore be organized around diagnosis, testing, management, prevention and safety rather than only disease facts.","type":"table","columns":["Official task/competency","Current range"],"rows":[["Diagnosis","16-20%"],["Laboratory/diagnostic studies","13-17%"],["Mixed management","12-16%"],["Pharmacotherapy","8-12%"],["Clinical interventions","6-10%"],["Health maintenance/disease prevention","5-10%"],["Prognosis/outcome","5-9%"],["Systems-based practice & patient safety","5-7%"],["Professionalism","5-7%"],["Practice-based learning & improvement","3-5%"]]},{"heading":"Clinical science weighting","type":"paragraph","text":"Medicine contributes 55-65%, Pediatrics 17-27%, OB/GYN 10-20%, Psychiatry 10-15%, and Surgery 5-15%, with substantial integration across disciplines. Official Step 2 CK specifications 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":64},{"name":"USMLE STEP 2 CK - CONTENT REVIEW STACK","list_label":"USMLE STEP 2 CK - CONTENT REVIEW STACK","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"","type":"table","columns":["Need","Recommended role","Why"],"rows":[["Clinical framework","OnlineMedEd or Boards & Beyond Step 2/3","Organizes diagnosis and management before/alongside questions."],["Primary Qbank","UWorld Step 2 CK","Longitudinal shelf + Step 2 learning through clinical vignettes and explanations."],["Targeted reference + extra questions","AMBOSS","Rapid lookup, management tables, targeted weak-area sessions."],["Case-based reasoning","Sketchy Cases","Optional case practice for differential, workup and management."],["Bedside/physical exam","Stanford Medicine 25 + Strong Medicine physical exam","Evidence-based bedside technique; complements supervised clinical skills."],["Official readiness","NBME CCSSA / self-assessments + official USMLE sample interface","Use serially; review every item and domain trend."]]},{"heading":"Step 2 question review prompt","type":"bullets","items":["What is the question asking: diagnosis, test, treatment, prevention, prognosis, ethics/safety?","Is the patient stable? What dangerous diagnosis must be addressed first?","What information is already sufficient - do I need another test?","What is the next step rather than the ultimate definitive step?","What would change management or disposition? 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":65},{"name":"USMLE STEP 2 CK - 4-6 WEEK DEDICATED TEMPLATE","list_label":"USMLE STEP 2 CK - 4-6 WEEK DEDICATED TEMPLATE","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"","type":"table","columns":["Phase","Focus"],"rows":[["Opening 3-4 days","Baseline CCSSA or school-approved assessment; build list by clerkship/system + error type."],["Weeks 1-2","Mixed UWorld/AMBOSS blocks; repair earliest/weakest clerkships; daily management algorithms; prevention/ethics/patient safety included."],["Weeks 2-4","Mostly mixed timed blocks; one targeted half-day per weak area; second CCSSA; deliberate abstract/quality/safety review."],["Weeks 4-5","High-frequency missed presentations; third assessment if needed; full-day endurance simulation; review notes from questions rather than rewatching broad content."],["Final 5-7 days","Recurring errors, vaccines/screening, biostats/ethics, emergency algorithms, common medication adverse effects, official practice interface; taper volume."]]},{"heading":"2026 testing format","type":"paragraph","text":"For exams on/after May 7, 2026, Step 2 CK uses sixteen 30-minute blocks in a 9-hour session, with no more than 20 questions per block. Endurance practice should reflect shorter but more frequent blocks. Official Step 2 CK page 2026/27 review-expanded edition - verify official exam updates before testing"}],"page":66},{"name":"COMLEX-USA LEVEL 2-CE - BLUEPRINT REVIEW","list_label":"COMLEX-USA LEVEL 2-CE - BLUEPRINT REVIEW","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"","type":"table","columns":["Dimension 1 competency domain","Minimum %"],"rows":[["Osteopathic Principles, Practice & Manipulative Treatment","10%"],["Osteopathic Patient Care & Procedural Skills","30%"],["Application of Knowledge for Osteopathic Medical Practice","26%"],["Practice-Based Learning & Improvement","7%"],["Interpersonal & Communication Skills","5%"],["Professionalism","7%"],["Systems-Based Practice","5%"]]},{"heading":"What changes from Step 2 preparation","type":"bullets","items":["Maintain the same clinical diagnosis/management core, but keep OPP/OMM active throughout clerkships and dedicated.","Use COMLEX-style questions for osteopathic framing, professionalism/communication and OMM integration.","Musculoskeletal remains an explicit 13% minimum clinical-presentation domain in the current blueprint.","Use COMSAE Phase 2 / school readiness requirements rather than assuming an NBME score alone answers COMLEX readiness. Official Level 2-CE page | COMLEX blueprint | COMSAE 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":67},{"name":"STEP 2 CK / LEVEL 2-CE - READINESS MATRIX","list_label":"STEP 2 CK / LEVEL 2-CE - READINESS MATRIX","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"","type":"table","columns":["Evidence","Ready signal","Concern signal"],"rows":[["Qbank","Improving mixed timed performance; explanations understood; repeat misses decreasing.","Repeated same presentations/management errors; poor time control; explanation review superficial."],["Shelf/COMAT","Clerkship exam trend stable/improving across disciplines.","One or more major clerkships remain unremediated."],["Official self-assessment","Multiple recent assessments broadly concordant and acceptable per school/exam plan.","Single isolated high score; large volatility; domain deficits not repaired."],["Endurance","Can sustain current exam block structure and recover during breaks.","Late-session collapse or rushing."],["Clinical reasoning","Can articulate differential -> test -> treatment -> disposition.","Knowledge facts known but next-step sequence repeatedly wrong."]]},{"heading":"Readiness thresholds should follow the learner’s school and official examination guidance. This Academy deliberately does not prescribe a universal “safe score” from one practice test.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":68},{"name":"STEP 3 + COMLEX LEVEL 3 - POST-GRADUATE REVIEW","list_label":"STEP 3 + COMLEX LEVEL 3 - POST-GRADUATE REVIEW","phase":"These are included as transition-to-residency tracks. They should not displace the Year 4 priority of supervised clinical","category":"Review System — Step 2 / Step 3","sections":[{"heading":"competence and residency readiness. USMLE Step 3","type":"bullets","items":["General ambulatory and acute care, diagnosis/management, prevention, longitudinal follow-up, biostatistics and prognosis.","Computer-based case simulations (CCS) require action sequencing, monitoring, reassessment and disposition.","Use UWorld Step 3 or AMBOSS USMLE for questions, plus official USMLE materials and an NBME Comprehensive Clinical Medicine self-assessment where appropriate."]},{"heading":"COMLEX Level 3","type":"bullets","items":["Independent osteopathic practice, OPP/OMM, clinical management and Clinical Decision-Making (CDM) cases.","NBOME changes Level 3 to a one-day exam effective Jan 13, 2027: 240 MCQs + 16 CDM cases; blueprint remains unchanged.","Use official CDM tutorial/practice, COMLEX-specific bank and COMSAE Phase 3 as appropriate. Official Level 3 | COMSAE 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":69},{"name":"CASE-SIMULATION REVIEW - CCS + CDM","list_label":"CASE-SIMULATION REVIEW - CCS + CDM","phase":"","category":"Review System — Step 2 / Step 3","sections":[{"heading":"Generic case method","type":"table","columns":["Step","Action"],"rows":[["1. Stabilize","Identify immediately dangerous problems; address ABCs and emergent treatment first."],["2. Acquire","Focused history/exam; order only tests that can change diagnosis/management."],["3. Interpret","Update differential using new data; stop unnecessary testing."],["4. Treat","Start evidence-based therapy; discontinue harmful/irrelevant interventions."],["5. Monitor","Reassess symptoms, vitals, labs and treatment response."],["6. Prevent / counsel","Vaccines, screening, medication counseling, risk reduction, adherence, safety."],["7. Disposition","Admit/discharge/consult/follow-up based on stability and care needs."]]},{"heading":"Review error types","type":"bullets","items":["Delayed stabilization.","Shotgun testing without decision value.","Correct treatment but wrong sequence.","Failure to reassess after intervention.","Missing preventive counseling/follow-up.","Unsafe disposition or failure to escalate. 2026/27 review-expanded edition - verify official exam updates before testing"]}],"page":70},{"name":"RESOURCE DECISION MATRIX","list_label":"RESOURCE DECISION MATRIX","phase":"","category":"Review System — Resource Strategy","sections":[{"heading":"Use the smallest resource stack that closes the learner’s actual gaps.","type":"table","columns":["Resource","Best use","Stage","Type"],"rows":[["Boards & Beyond","Structured preclinical / board content review; also clinical/OMM series.","M1-M2; boards","Video + questions"],["Med School Bootcamp","Integrated Step 1-oriented review, anatomy/histology, linked review videos/questions.","M1-M2; Step 1","Video + Qbank"],["Pathoma","Mechanistic pathology consolidation across organ systems.","M1-M2; Step 1","Video + text"],["Sketchy","Visual memory for micro/pharm/path and broader medical content.","M1-M3","Video + memory"],["Ninja Nerd","Deep mechanism repair in physiology, pharmacology and disease.","Any","Long-form video"],["OnlineMedEd","Clinical framework for clerkships and Step/Level 2.","M3-M4","Clinical video + Qbank"],["Stanford Medicine 25","Bedside examination demonstrations.","M1-M4","Clinical video"],["Strong Medicine physical exam","Evidence-based physical examination and clinical reasoning.","M1-M4","Free video"],["UWorld","Primary vignette-based learning and exam practice.","Boards/clerkships","Qbank"],["AMBOSS","Reference library, targeted Qbank, school + board integration.","All years","Library + Qbank"],["TrueLearn COMLEX","COMLEX/COMAT-oriented question practice and osteopathic framing.","DO M1-M4","Qbank"],["NBME assessments","Official-style readiness for Step/Shelf pathways.","Boards/clerkships","Self-assessment"],["COMSAE 2026/27 review-expanded edition - verify official exam updates before testing","COMLEX readiness assessment in osteopathic pathway.","DO boards","Self-assessment"]]}],"page":71},{"name":"THE “ONE + ONE + OFFICIAL + TARGETED” RULE","list_label":"THE “ONE + ONE + OFFICIAL + TARGETED” RULE","phase":"","category":"Review System — Resource Strategy","sections":[{"heading":"Default stack","type":"bullets","items":["ONE primary content system for structured review when needed.","ONE primary question bank used deeply and longitudinally.","OFFICIAL blueprint + official assessments to define scope and readiness.","TARGETED supplements only when a specific weak domain justifies them."]},{"heading":"Default stack — Examples","type":"table","columns":["Learner state","Efficient stack"],"rows":[["Strong school foundation, Step 1 weak in pathology","UWorld + Pathoma + NBME; no need to restart a full video curriculum."],["Weak renal physiology","Primary Qbank + Ninja Nerd renal/physiology deep dive + targeted renal questions + retest."],["DO student strong biomedical but weak OMM","COMLEX bank + school OMM lab/review + OMM video series + COMSAE; maintain mixed biomedical questions."],["Clinical student weak management sequence","UWorld/AMBOSS + OnlineMedEd targeted algorithm review + NBME CSMS + illness-script drills."]]},{"heading":"Resource overload warning — Adding a new platform should solve a defined problem: conceptual gap, memory gap, practice-volume gap, clinical-reasoning gap, or assessment gap. If it does not, it is probably adding friction rather than mastery.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":72},{"name":"OFFICIAL + CURATED REVIEW SOURCES","list_label":"OFFICIAL + CURATED REVIEW SOURCES","phase":"","category":"Review System — Resource Strategy","sections":[{"heading":"Official exam / assessment sources","type":"bullets","items":["USMLE Step 1 content & specifications","USMLE Step 2 CK content & specifications","USMLE Step 3 content & specifications","NBME self-assessments","NBME Clinical Science Mastery Series","NBOME COMLEX-USA Blueprint","COMLEX Level 1 official page","COMLEX Level 2-CE official page","COMLEX Level 3 official page","COMSAE","COMAT Clinical Subject Exams"]},{"heading":"Curated review resources","type":"bullets","items":["Boards & Beyond","Med School Bootcamp","Pathoma","Sketchy Medical","Ninja Nerd","OnlineMedEd","Stanford Medicine 25","Strong Medicine - evidence-based physical exam course","Strong Medicine - systematic ECG interpretation","UWorld Step 1","UWorld Step 2 CK","UWorld Step 3","AMBOSS","TrueLearn COMLEX"]},{"heading":"Resource descriptions in this Academy are based on current official/provider-published scope and instructional fit; they are not guarantees of exam outcomes. Official examination organizations and the learner’s school remain the source of truth for eligibility, format, scoring and required assessments.","type":"paragraph","text":"2026/27 review-expanded edition - verify official exam updates before testing"}],"page":73}];
